/* テキスト拡充・第4弾(担当:sci1 中学理科・理科基礎・情報・科学と人間生活) */
(function (L) {
  function add(id, o) { var x = L[id]; if (!x) return; ['pat', 'more'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); }); }

  add('s_light', {
    pat: [
      { name: '凸レンズの像の位置・大きさ・向き', freq: 'とてもよく出る', when: '「焦点距離」「物体をレンズから○cmの位置に」「スクリーンにはっきりした像」とあれば、この型です。', how: ['物体が焦点の外か内かを最初に確かめます(外なら実像、内なら虚像)。', '実像なら 1/a + 1/b = 1/f(a:物体〜レンズ、b:レンズ〜像)で像の位置 b を出します。', '像の大きさは「物体の大きさ × b/a」で求めます(距離の比と大きさの比は同じ)。', '実像は上下左右が逆(倒立)、虚像は同じ向き(正立)と答えます。'], ex: { q: '焦点距離8cmの凸レンズの前24cmの所に、高さ6cmの物体を置いた。像ができる位置と高さ、向きは?', a: 'レンズの後ろ12cm、高さ3cm、倒立の実像', exp: '1/b = 1/8 − 1/24 = 3/24 − 1/24 = 2/24 = 1/12 なので b = 12cm です。大きさは 6 × 12/24 = 3cm。物体は焦点の外にあるので、スクリーンにうつる倒立の実像になります。' } },
      { name: '音の往復・時間差から距離を求める', freq: 'とてもよく出る', when: '「こだま」「はね返った音」「見えてから聞こえるまで」「2回聞こえた」とあれば、この型です。', how: ['音が進んだ道すじを図にかき、片道か往復かを確かめます。', '往復なら「速さ × 時間 ÷ 2」が片道の距離です。', '光は一瞬で届くと考えてよいので、「見えてから聞こえるまで」は音だけの時間です。', '伝わる物質が2つあるときは、それぞれの時間を式にして「時間の差」で式を立てます。'], ex: { q: '校舎のかべに向かって手をたたくと、0.5秒後にはね返った音が聞こえた。かべまでの距離は何m?(音の速さは340m/s)', a: '85m', exp: '音はかべまで行って帰ってくるので、0.5秒間に進んだ 340 × 0.5 = 170m は往復の距離です。片道はその半分で 170 ÷ 2 = 85m。÷2 を忘れて170mと答えるまちがいが多いです。' } },
      { name: '平面鏡の像は「線対称」で考える', freq: 'よく出る', when: '「鏡にうつった像」「鏡に近づく」「鏡で見える範囲」とあれば、この型です。', how: ['像は鏡の面を折り目にした線対称の位置(鏡の奥、同じ距離)にできます。', '自分が鏡に近づくと、像も同じだけ鏡に近づきます。', '見えるかどうかは、像と目を直線で結び、その線が鏡の面を通るかで判断します。'], ex: { q: 'かべにかけた大きな鏡に向かって、1.5m/sの速さでまっすぐ歩いた。自分と鏡の中の自分の像は、1秒間に何mずつ近づく?', a: '3m', exp: '1秒で自分は鏡に1.5m近づき、像も鏡の奥から1.5m鏡に近づきます。2つが近づく距離は 1.5 + 1.5 = 3m です。像は動かないと考えて1.5mと答えないよう注意します。' } },
      { name: 'オシロスコープの波形の読み取り', freq: 'よく出る', when: '「波形」「横軸1目もり○秒」「振幅」とあり、2つの音をくらべるときは、この型です。', how: ['たてのはば(振幅)が大きいほど、大きい音です。', '1回の振動(山から次の山まで)の目もり数 × 1目もりの時間 = 1回の振動の時間です。', '振動数 = 1 ÷ 1回の振動の時間。振動数が大きいほど高い音です。'], ex: { q: '横軸1目もりが0.0005秒の画面で、ある音の1回の振動が8目もり分だった。振動数は何Hz?', a: '250Hz', exp: '1回の振動にかかる時間は 0.0005 × 8 = 0.004秒です。1秒間の振動の回数は 1 ÷ 0.004 = 250回なので、250Hz です。目もりの数をそのまま振動数と考えないようにします。' } },
      { name: '屈折の向きと全反射の判断', freq: 'よく出る', when: '「空気から水へ」「水から空気へ」「浮き上がって見える」「光ファイバー」とあれば、この型です。', how: ['角度は境目の面ではなく、面に垂直な線(法線)からはかります。', '空気 → 水・ガラスでは、屈折角 < 入射角(法線に近づく)。', '水・ガラス → 空気では、屈折角 > 入射角(法線から遠ざかる)。', '水・ガラス → 空気で入射角を大きくしていくと、ある角度から光が全部はね返る(全反射)。'], ex: { q: 'ガラスの中から空気中へ光が進むとき、入射角をだんだん大きくした。屈折した光はやがてどうなる?', a: '屈折角が90°に近づき、やがて屈折光がなくなって、光はすべて反射する(全反射)。', exp: 'ガラス → 空気では屈折角が入射角より大きいので、入射角より先に屈折角が90°に達します。それ以上入射角を大きくすると空気中へ出られず、すべて反射します。これが全反射です。' } }
    ],
    more: [
      { lv: 1, q: '鏡の面と入ってくる光とのなす角が35°だった。反射角は何度?', a: '55°', exp: '入射角・反射角は鏡の面に垂直な線(法線)からはかります。入射角は 90 − 35 = 55° で、反射角 = 入射角 なので55°です。35°と答えるまちがいに注意します。' },
      { lv: 1, q: '太陽や電灯のように、自分で光を出すものを何という?', a: '光源', exp: '自分で光を出すものを光源といいます。月や本などは自分では光を出さず、光源の光をはね返しているので、その光が目に入って見えます。' },
      { lv: 1, q: '光が空気中から水面に垂直に入るとき、光はどう進む?', a: '曲がらずにそのまま直進する。', exp: '入射角が0°のときは屈折角も0°で、境目で曲がりません。屈折が起こるのは、境目に対してななめに光が入るときです。' },
      { lv: 1, q: '凸レンズの軸(光軸)に平行に入った光は、レンズを通ったあとどう進む?', a: '反対側の焦点を通る。', exp: '光軸に平行な光は、レンズで屈折して反対側の焦点に集まります。作図で使う代表の光の1本です。逆に、焦点を通ってからレンズに入った光は光軸に平行に進みます。' },
      { lv: 1, q: '音の大きさを決めるものはどれ?', choices: ['A 振動数', 'B 振幅', 'C 音の速さ', 'D 音源までの距離だけ'], a: 'B(振幅)', exp: '振幅(ふれはば)が大きいほど大きい音になります。振動数は音の高さを決めます。音の速さは大きさや高さでは変わりません。' },
      { lv: 1, q: '表面にでこぼこがある物体に光が当たり、いろいろな方向にはね返ることを何という?', a: '乱反射', exp: '乱反射でも、光の1本1本は「入射角 = 反射角」で反射しています。面の向きがばらばらなので、いろいろな方向に広がり、どこから見ても物体が見えます。' },
      { lv: 1, q: '鳴っている音さを水面にふれさせると、水しぶきが上がった。このことから分かることは?', a: '音を出している物体は振動している。', exp: '音は物体の振動によって生じ、その振動がまわりの空気などを次々に振動させて伝わります。音さの振動が水をはね上げたのです。' },
      { lv: 2, q: '稲妻が光ってから4秒後に雷の音が聞こえた。雷が発生した場所までの距離は何m?(音の速さは340m/s)', a: '1360m', exp: '光はほぼ一瞬で届くので、4秒は音が伝わる時間です。340 × 4 = 1360m。こちらは往復ではないので2でわりません。' },
      { lv: 2, q: '焦点距離6cmの凸レンズで、物体と同じ大きさの実像をスクリーンにうつした。物体とスクリーンの間の距離は何cm?', a: '24cm', exp: '同じ大きさの実像ができるのは、物体を焦点距離の2倍(12cm)の位置に置いたときで、像もレンズの反対側12cmにできます。物体〜スクリーンは 12 + 12 = 24cm です。' },
      { lv: 2, q: 'オシロスコープで音Aと音Bの波形をくらべると、振幅は同じで、1回の振動にかかる時間はBがAの半分だった。正しいものはどれ?', choices: ['A BはAより大きい音', 'B BはAより低い音', 'C BはAより高い音で、大きさは同じ', 'D BはAより小さく低い音'], a: 'C(BはAより高い音で、大きさは同じ)', exp: '1回の振動の時間が半分なら、振動数は2倍で高い音です。振幅が同じなので大きさは同じです。時間が短い=振動数が大きい、の関係に注意します。' },
      { lv: 2, q: '入射光と反射光のなす角が100°だった。入射角は何度?', a: '50°', exp: '入射光と反射光は法線をはさんで対称なので、入射角と反射角は等しく、合計が100°です。100 ÷ 2 = 50° です。' },
      { lv: 2, q: '運動会で、ゴールの係の人がスタートのピストルの煙を見てから0.3秒後に音を聞いた。スタートからゴールまでは何m?(音の速さは340m/s)', a: '102m', exp: '煙(光)はすぐに届くので、0.3秒は音が伝わる時間です。340 × 0.3 = 102m。音を聞いてから時計を押すと、約0.3秒おそく記録されることになります。' },
      { lv: 2, q: '焦点距離の2倍より遠い所にある物体を、さらにレンズから遠ざけた。スクリーンにできる実像はどうなる?', choices: ['A 大きくなり、レンズから遠ざかる', 'B 小さくなり、焦点に近づく', 'C 大きさは変わらない', 'D 虚像に変わる'], a: 'B(小さくなり、焦点に近づく)', exp: '物体が遠いほど、像はレンズに近づいて焦点の位置に近づき、小さくなります(大きさは b/a 倍)。逆に物体が焦点に近づくほど、像は遠く大きくなります。' },
      { lv: 2, q: '実像と虚像のうち、スクリーンにうつすことができるのはどちら?', a: '実像', exp: '実像は光が実際に集まってできる像なので、スクリーンにうつります。虚像は光を逆向きにのばした先に見える像で、光が集まっていないのでうつりません。' },
      { lv: 2, q: '空気中から水中へ光がななめに入るとき、入射角を30°から50°に大きくした。屈折角はどうなる?', a: '大きくなるが、いつも入射角より小さい。', exp: '入射角を大きくすると屈折角も大きくなります。ただし空気 → 水では、光は法線に近づくように曲がるので、屈折角はつねに入射角より小さいままです。' },
      { lv: 3, q: '焦点距離12cmの凸レンズの前18cmの所に、高さ2cmの物体を置いた。像の位置と高さは?', a: 'レンズの後ろ36cm、高さ4cm(倒立の実像)', exp: '1/b = 1/12 − 1/18 = 3/36 − 2/36 = 1/36 より b = 36cm。像の高さは 2 × 36/18 = 4cm。物体が f と 2f の間にあるので、拡大された倒立の実像です。' },
      { lv: 3, q: '焦点距離10cmの凸レンズで、物体をレンズから30cmの所から15cmの所へ動かした。はっきりした像をうつし続けるには、スクリーンをどちらへ何cm動かす?また、像の高さは何倍になる?', a: 'レンズから遠ざける向きに15cm。像の高さは4倍。', exp: 'a = 30 のとき 1/b = 1/10 − 1/30 = 1/15 で b = 15。a = 15 のとき 1/b = 1/10 − 1/15 = 1/30 で b = 30。スクリーンは15cm遠ざけます。倍率は 15/30 = 0.5倍 から 30/15 = 2倍 になるので4倍です。' },
      { lv: 3, q: '船が岸壁に向かって10m/sで進みながら汽笛を鳴らすと、4秒後に岸壁ではね返った音が聞こえた。汽笛を鳴らしたとき、船から岸壁までは何mだった?(音の速さは340m/s)', a: '700m', exp: '4秒間に音が進んだ 340 × 4 = 1360m と、船が進んだ 10 × 4 = 40m の和が、はじめの距離の2倍です。(1360 + 40) ÷ 2 = 700m。船が動く分を足すのがポイントです。' },
      { lv: 3, q: '2枚の平面鏡を、鏡の面どうしが60°になるように立て、その間に物体を置いた。鏡にうつって見える像はいくつ?', a: '5つ', exp: '鏡どうしの角度が θ のとき、像の数は 360 ÷ θ − 1 になります(360 ÷ θ が偶数のとき)。360 ÷ 60 − 1 = 5。90°なら3つで、角度が小さいほど像は増えます。' },
      { lv: 3, q: '水そうの水面を、水中からななめ下から見上げると、水面が鏡のように光って見えることがある。この理由として正しいものはどれ?', choices: ['A 光が水面で乱反射するから', 'B 水中から空気へ向かう光が、水面ですべて反射するから', 'C 空気中から水中へ入る光が全反射するから', 'D 光が水中で直進しなくなるから'], a: 'B(水中から空気へ向かう光が、水面ですべて反射するから)', exp: '水 → 空気の向きで入射角が大きいと、光は空気中へ出られずすべて反射します(全反射)。全反射は、光が水やガラスから空気へ進むときにしか起こりません。' }
    ]
  });

  add('s_force', {
    pat: [
      { name: 'ばねの「のび」と「長さ」の読み分け', freq: 'とてもよく出る', when: '「もとの長さ(自然長)」「ばねの長さ」「グラフ」とあれば、この型です。', how: ['問われているのが「のび」か「ばね全体の長さ」かを先に確かめます。', '長さ − 自然長 = のび。比例するのは「のび」だけです。', '1Nあたり何cmのびるかを出し、力に比例させてのびを計算します。', '最後に、長さを聞かれていたら自然長を足します。'], ex: { q: '自然長12cmのばねに0.5Nのおもりをつるすと、長さが14cmになった。1.5Nのおもりをつるすと、長さは何cm?', a: '18cm', exp: '0.5Nでのびは 14 − 12 = 2cm なので、1Nで4cmのびます。1.5Nでは 4 × 1.5 = 6cm のびるので、長さは 12 + 6 = 18cm です。14 × 3 = 42cm とするのはまちがいです。' } },
      { name: '置き方・重ね方を変えた圧力の比較', freq: 'とてもよく出る', when: '「面を下にして置く」「重ねる」「圧力が最大・最小」とあれば、この型です。', how: ['力(重さ)は置き方で変わらず、変わるのは面積だけと確認します。', '面積は cm² から m² に直します(1cm² = 0.0001m²)。', '圧力 = 力 ÷ 面積。重ねたら力が足し算になります。', '比をくらべるときは「力の比 ÷ 面積の比」で考えると速いです。'], ex: { q: '重さ8Nの同じ直方体を2個重ね、5cm×4cmの面を下にして置いた。床が受ける圧力は何Pa?', a: '8000Pa', exp: '力は 8 × 2 = 16N、面積は 20cm² = 0.002m² です。圧力 = 16 ÷ 0.002 = 8000Pa。面積を cm² のまま計算すると答えがまちがった桁になります。' } },
      { name: '浮力から体積・密度を求める', freq: 'よく出る', when: '「空気中で○N、水中で○N」「ばねばかり」とあれば、この型です。', how: ['浮力 = 空気中の値 − 水中の値。', '浮力の大きさは、おしのけた水の重さ。水1cm³ = 1g、100g = 1N から、体積が出ます。', '空気中の値から質量を出し、密度 = 質量 ÷ 体積 で物質を考えます。'], ex: { q: 'ある金属をばねばかりにつるすと、空気中で2.7N、全部水にしずめると1.7Nだった。この金属の密度は何g/cm³?', a: '2.7g/cm³', exp: '浮力は 2.7 − 1.7 = 1.0N で、おしのけた水は100g、つまり体積100cm³です。質量は270gなので、密度 = 270 ÷ 100 = 2.7g/cm³(アルミニウムに近い値)です。' } },
      { name: '浮く・しずむと、水面下の体積', freq: 'よく出る', when: '「水に浮かんで静止」「水面から出ている部分」「密度」とあれば、この型です。', how: ['物体の密度が水(1g/cm³)より小さければ浮き、大きければしずみます。', '浮いて止まっているときは、浮力 = 物体の重さ(つりあい)。', '浮力 = 水中部分の体積の水の重さ なので、水中部分の体積が求まります。'], ex: { q: '質量60g、体積80cm³の物体を水に入れた。浮くか、しずむか。浮くなら水中部分の体積は?', a: '浮く。水中部分は60cm³', exp: '密度は 60 ÷ 80 = 0.75g/cm³ で、水より小さいので浮きます。浮いて止まると浮力は重さと同じ0.6Nで、これは水60cm³分の重さなので、水中部分は60cm³です。' } },
      { name: 'つりあいの2力と作用・反作用の2力の区別', freq: 'よく出る', when: '「つりあっている2力」「作用・反作用の関係にある2力」を選ばせる問題は、この型です。', how: ['それぞれの力について「何が、何を」おしているか(引いているか)を書き出します。', '同じ物体にはたらく2力ならつりあい、2つの物体の間でおし合う2力なら作用・反作用です。', 'どちらも「同じ大きさ・反対向き・一直線上」なので、大きさでは区別できません。'], ex: { q: '机の上に置いた本について、「本が机をおす力」と作用・反作用の関係にある力は?', a: '机が本をおす力(垂直抗力)', exp: '「本が机を」の主語と目的語を入れかえた「机が本を」おす力が反作用です。本にはたらく重力は「地球が本を」引く力で、机が本をおす力とつりあいの関係になります。' } }
    ],
    more: [
      { lv: 1, q: 'ばねののびが、ばねを引く力の大きさに比例するという法則を何という?', a: 'フックの法則', exp: 'ばねののびは力に比例します(フックの法則)。比例するのは「のび」で、ばね全体の長さではない点に注意します。' },
      { lv: 1, q: '質量300gの物体にはたらく重力は何N?(100gの物体にはたらく重力を1Nとする)', a: '3N', exp: '100gで1Nなので、300gでは 300 ÷ 100 = 3N です。gは質量、Nは力の単位で、別のものであることを意識します。' },
      { lv: 1, q: '力を矢印で表すとき、矢印で表す3つの要素は?', a: '作用点・力の向き・力の大きさ', exp: '矢印の始点が作用点、矢印の向きが力の向き、矢印の長さが力の大きさを表します。この3つを力の三要素といいます。' },
      { lv: 1, q: '包丁の刃をといでうすくすると、よく切れるようになる理由を「圧力」を使って説明すると?', a: '力がはたらく面積が小さくなり、同じ力でも圧力が大きくなるから。', exp: '圧力 = 力 ÷ 面積 なので、面積が小さいほど圧力は大きくなります。逆に、雪の上でスキー板をはくのは、面積を大きくして圧力を小さくするためです。' },
      { lv: 1, q: '水中の物体が受ける水圧は、どの向きからはたらく?', a: 'あらゆる向きから、物体の面に垂直にはたらく。', exp: '水圧は上からだけでなく、横や下からもはたらきます。深いところほど大きく、同じ深さならどの向きでも同じ大きさです。' },
      { lv: 1, q: '床の上の箱を右向きにおしたが、箱は動かなかった。箱にはたらく摩擦力の向きは?', choices: ['A 右向き', 'B 左向き', 'C 上向き', 'D 摩擦力ははたらいていない'], a: 'B(左向き)', exp: '摩擦力は、物体が動こうとする向きと反対向きにはたらきます。動かないときは、おす力と同じ大きさの摩擦力が左向きにはたらいて、つりあっています。' },
      { lv: 1, q: 'ばねばかりにつるした物体を水に入れると、ばねばかりの値はどうなる?また、その理由は?', a: '小さくなる。水から上向きの浮力を受けるから。', exp: '水中の物体は、上向きの浮力を受けます。その分だけばねばかりが引く力は小さくてすみ、目もりが小さくなります。' },
      { lv: 2, q: '自然長10cmのばねに0.4Nの力を加えると、長さが12cmになった。1.0Nの力を加えると、ばねの長さは何cm?', a: '15cm', exp: '0.4Nでのびは2cmなので、1Nあたり5cmのびます。1.0Nでは5cmのびて、長さは 10 + 5 = 15cm です。「長さ」と「のび」を区別します。' },
      { lv: 2, q: '重さ12Nの直方体を、たて4cm・横5cmの面を下にして床に置いた。床が受ける圧力は何Pa?', a: '6000Pa', exp: '面積は 4 × 5 = 20cm² = 0.002m² です。圧力 = 12 ÷ 0.002 = 6000Pa。1cm² = 0.0001m² の換算がポイントです。' },
      { lv: 2, q: '物体をばねばかりにつるすと、空気中で3.9N、全部を水にしずめると3.4Nだった。この物体の体積と密度は?(水1cm³は1g、100gの物体にはたらく重力を1Nとする)', a: '体積50cm³、密度7.8g/cm³', exp: '浮力は 3.9 − 3.4 = 0.5N で、おしのけた水は50g = 50cm³ です。質量は390gなので、密度は 390 ÷ 50 = 7.8g/cm³(鉄に近い値)です。' },
      { lv: 2, q: '机の上にりんごが置いてある。作用・反作用の関係にある2力の組み合わせはどれ?', choices: ['A りんごにはたらく重力と、机がりんごをおす力', 'B りんごが机をおす力と、机がりんごをおす力', 'C りんごにはたらく重力と、りんごが机をおす力', 'D 机にはたらく重力と、机が床をおす力'], a: 'B(りんごが机をおす力と、机がりんごをおす力)', exp: '作用・反作用は「AがBを」と「BがAを」の組です。Aは同じりんごにはたらく2力なので、つりあいの関係です。' },
      { lv: 2, q: '水深20cmの所と水深60cmの所では、水圧の大きさの比はいくら?', a: '1:3', exp: '水圧は、その上にある水の重さによるので、深さに比例します。20:60 = 1:3 です。容器の形や底の広さには関係しません。' },
      { lv: 2, q: '物体に左向き5N、右向き3Nの力がはたらいている。もう1つ力を加えて3力をつりあわせるには、どの向きに何Nの力を加えればよい?', a: '右向きに2N', exp: '左向き5Nと右向き3Nの合力は左向き2Nです。これを打ち消すには、反対の右向きに2Nの力を加えます。' },
      { lv: 2, q: '質量60g、体積80cm³の物体を水に入れて静止させた。物体にはたらく浮力は何N?(100gの物体にはたらく重力を1Nとする)', a: '0.6N', exp: '密度は 0.75g/cm³ で水より小さいので浮きます。浮いて静止すると浮力と重力がつりあうので、浮力は重さと同じ0.6Nです。体積80cm³分の0.8Nとするのはまちがいです。' },
      { lv: 2, q: '大気圧が100000Paのとき、面積0.5m²の机の上の面が大気から受ける力は何N?', a: '50000N', exp: '力 = 圧力 × 面積 = 100000 × 0.5 = 50000N。こんなに大きな力でも机がつぶれないのは、机の下側や内部からも大気圧が同じようにおしているからです。' },
      { lv: 3, q: '1Nで2cmのびるばねAと、1Nで3cmのびるばねBを、たてにつないで1.5Nのおもりをつるした。2本合わせたのびは何cm?(ばねの重さは考えない)', a: '7.5cm', exp: 'たてにつなぐと、どちらのばねにも1.5Nがかかります。Aは 2 × 1.5 = 3cm、Bは 3 × 1.5 = 4.5cm のびるので、合わせて 7.5cm です。' },
      { lv: 3, q: 'たて10cm・横5cm・高さ4cmで重さ8Nの直方体がある。この直方体を2個重ねて最も小さい面を下にしたときの圧力は、1個を最も大きい面を下にして置いたときの何倍?', a: '5倍', exp: '2個で最小面(5×4 = 20cm² = 0.002m²)なら 16 ÷ 0.002 = 8000Pa。1個で最大面(10×5 = 50cm² = 0.005m²)なら 8 ÷ 0.005 = 1600Pa。8000 ÷ 1600 = 5倍です。' },
      { lv: 3, q: '空気中で1.2Nを示す、体積100cm³の物体をばねばかりにつるし、体積の半分だけを水に入れた。ばねばかりは何Nを示す?(水1cm³は1g、100gの物体にはたらく重力を1Nとする)', a: '0.7N', exp: '水中の部分は50cm³なので、浮力は水50g分の0.5Nです。ばねばかりは 1.2 − 0.5 = 0.7N を示します。浮力は物体全体ではなく、水中部分の体積で決まります。' },
      { lv: 3, q: '全部が水中にある物体を、さらに深い所へしずめていった(底にはつかない)。物体にはたらく浮力はどうなる?', choices: ['A 深いほど大きくなる', 'B 深いほど小さくなる', 'C 変わらない', 'D 0になる'], a: 'C(変わらない)', exp: '深くなると上の面も下の面も水圧が大きくなりますが、その差(上下の深さの差による分)は同じです。浮力は上下の水圧の差なので、全部しずんだあとは深さで変わりません。' },
      { lv: 3, q: '体積50cm³の物体を、ある食塩水の中に全部しずめると、浮力は0.6Nだった。この食塩水の密度は何g/cm³?(100gの物体にはたらく重力を1Nとする)', a: '1.2g/cm³', exp: '浮力0.6Nは、おしのけた食塩水60g分の重さです。体積は50cm³なので、密度は 60 ÷ 50 = 1.2g/cm³。水より密度の大きい液体ほど、浮力は大きくなります。' }
    ]
  });

  add('s_m1', {
    pat: [
      { name: '直列・並列が混ざった回路の電流と電圧', freq: 'とてもよく出る', when: '回路図に、枝分かれした部分と1本道の部分が両方あれば、この型です。', how: ['並列の部分をまとめて1つの抵抗にします(1/R = 1/R₁ + 1/R₂)。', '1本道になったら全体の抵抗を足し算し、全体の電流 = 電源の電圧 ÷ 全体の抵抗。', 'まとめた部分にかかる電圧 = 全体の電流 × まとめた抵抗。', 'その電圧を使って、枝分かれしたそれぞれの電流を求めます。'], ex: { q: '4Ωの抵抗2本を並列にした部分に、1Ωの抵抗を直列につなぎ、6Vの電源につないだ。4Ωの抵抗1本に流れる電流は?', a: '1A', exp: '並列部分は 1/R = 1/4 + 1/4 より 2Ω。全体は 2 + 1 = 3Ω で、電流は 6 ÷ 3 = 2A。並列部分の電圧は 2 × 2 = 4V なので、4Ω 1本には 4 ÷ 4 = 1A 流れます。' } },
      { name: '電熱線の発熱と水の温度上昇', freq: 'とてもよく出る', when: '「電熱線」「水○gを○分間」「水温が上がった」とあれば、この型です。', how: ['電力(W)= 電圧 × 電流 を出します。', '発熱量(J)= 電力 × 時間(秒)。分は秒に直します。', '水1gを1℃上げるのに約4.2J なので、上昇温度 = 熱量 ÷(4.2 × 水の質量)。'], ex: { q: '6V-9Wの電熱線を6Vで使い、150gの水を7分間あたためた。熱がすべて水に伝わるとすると、水温は何℃上がる?', a: '6℃', exp: '発熱量は 9 × 420 = 3780J です。上昇温度は 3780 ÷(4.2 × 150)= 3780 ÷ 630 = 6℃。7分を420秒に直すのを忘れないようにします。' } },
      { name: '電流計・電圧計の目もりの読み', freq: 'よく出る', when: '「−端子を○につないだ」「針が図のようにふれた」とあれば、この型です。', how: ['どの−端子につないだかを見て、目もりのいちばん右がその値になると考えます。', '目もり板の数字を、その端子の最大値に合わせて読みかえます。', '大きさが分からないときは、まず最大の端子(5Aや300V)につなぎます。'], ex: { q: '電流計の−端子を5Aにつなぐと、針は目もり板の「3.2」(いちばん右が5)を指した。電流は何A?', a: '3.2A', exp: '5A端子では目もり板のいちばん右が5Aになるので、数字をそのまま読んで3.2Aです。もし500mA端子なら、同じ位置は320mAと読みかえます。' } },
      { name: '電流・磁界・力の向き(どれを逆にするか)', freq: 'よく出る', when: '「電流の向きを逆に」「磁石の極を逆に」「コイルの動く向き」とあれば、この型です。', how: ['電流の向きか磁界の向きのどちらか1つを逆にすると、力の向きは逆になります。', '両方を逆にすると、力の向きはもとと同じです。', '力を大きくするには、電流を大きくする・磁石を強くする(コイルの巻数を増やす)。'], ex: { q: '磁石の間の導線に電流を流すと、導線は手前に動いた。電流の向きと磁石のN極・S極の向きを両方とも逆にすると、導線はどちらに動く?', a: '手前に動く(向きは変わらない)。', exp: '電流を逆にすると力は逆向き、さらに磁界も逆にすると、もう一度逆向きになってもとにもどります。「逆の逆はもとと同じ」と考えます。' } },
      { name: '電磁誘導の検流計のふれ', freq: 'よく出る', when: '「磁石をコイルに近づける・遠ざける」「検流計の針」とあれば、この型です。', how: ['近づける⇔遠ざける、N極⇔S極 のどちらか1つが変われば、ふれる向きは逆になります。', '両方変われば、ふれる向きは同じです。', '磁石を止めると電流は流れません。速く動かす・強い磁石・巻数を多くすると大きくふれます。'], ex: { q: 'N極をコイルに近づけると、検流計の針は右にふれた。S極をコイルから遠ざけると、針はどちらにふれる?', a: '右', exp: 'N極→S極で1回逆、近づける→遠ざけるでもう1回逆になるので、もとと同じ右にふれます。電流は、磁界の変化をさまたげる向きに流れます。' } }
    ],
    more: [
      { lv: 1, q: '20Ωの抵抗に0.3Aの電流が流れている。抵抗にかかる電圧は何V?', a: '6V', exp: 'オームの法則 電圧 = 抵抗 × 電流 より、20 × 0.3 = 6V です。V = RI の形で覚えると、どの量を求めるときも使えます。' },
      { lv: 1, q: '直列回路で、それぞれの抵抗に流れる電流の大きさはどうなっている?', a: 'どこでも同じ大きさ。', exp: '直列回路は1本道なので、電流はどこでも同じです。電圧は、それぞれの抵抗に分かれてかかり、合計が電源の電圧になります。' },
      { lv: 1, q: '並列回路で、それぞれの抵抗にかかる電圧の大きさはどうなっている?', a: 'どれも電源の電圧と同じ。', exp: '並列回路では、どの道すじにも電源と同じ電圧がかかります。電流は道すじごとに分かれ、その合計が全体の電流になります。' },
      { lv: 1, q: '6Vの電圧で0.5Aの電流が流れる電球の電力は何W?', a: '3W', exp: '電力 = 電圧 × 電流 = 6 × 0.5 = 3W です。電力が大きいほど、電球は明るく光ります。' },
      { lv: 1, q: '1Whは何J?', a: '3600J', exp: '1Wの電力で1時間(3600秒)使ったときの電力量が1Whです。J = W × 秒 なので、1 × 3600 = 3600J です。' },
      { lv: 1, q: '10Wの電熱線に1分間電流を流した。発熱量は何J?', a: '600J', exp: '発熱量 = 電力 × 時間(秒)= 10 × 60 = 600J です。時間を「分」のまま計算すると10Jとまちがえます。' },
      { lv: 1, q: '発電機が電気をつくり出すときに利用している現象は?', a: '電磁誘導', exp: 'コイルの中の磁界が変化すると、コイルに電圧が生じて電流が流れます。これが電磁誘導で、発電所の発電機もこのしくみです。' },
      { lv: 2, q: '6Ωと12Ωの抵抗を並列につなぎ、6Vの電源につないだ。電源から流れる電流は何A?', a: '1.5A', exp: '並列なのでどちらにも6Vがかかります。6Ωには 6 ÷ 6 = 1A、12Ωには 6 ÷ 12 = 0.5A。合計で1.5Aです(全体の抵抗は 6 ÷ 1.5 = 4Ω)。' },
      { lv: 2, q: '3Ωと9Ωの抵抗を直列につなぎ、6Vの電源につないだ。9Ωの抵抗にかかる電圧は何V?', a: '4.5V', exp: '全体の抵抗は12Ωで、電流は 6 ÷ 12 = 0.5A。9Ωにかかる電圧は 9 × 0.5 = 4.5V です。直列では、抵抗の比 3:9 で電圧が分かれます。' },
      { lv: 2, q: '電流計の−端子を500mAにつなぐと、針は目もり板の「2.4」(いちばん右が5)を指した。電流は何mA?', a: '240mA', exp: '500mA端子では、目もり板の5が500mAになるので、2.4は240mAと読みます。A に直すと0.24Aです。' },
      { lv: 2, q: '3Vの電圧で1Aの電流が流れる電熱線で、50gの水を3分30秒あたためた。熱がすべて水に伝わるとすると、水温は何℃上がる?(水1gを1℃上げるのに4.2J)', a: '3℃', exp: '電力は3W、時間は210秒なので、発熱量は 3 × 210 = 630J。上昇温度は 630 ÷(4.2 × 50)= 630 ÷ 210 = 3℃ です。' },
      { lv: 2, q: 'コイルのまわりにできる磁界を強くする方法として、まちがっているものはどれ?', choices: ['A コイルの巻数を多くする', 'B 流す電流を大きくする', 'C コイルに鉄心を入れる', 'D 電流の向きを逆にする'], a: 'D(電流の向きを逆にする)', exp: '電流の向きを逆にすると、磁界の向きが逆になるだけで、強さは変わりません。強くするには、巻数・電流を増やすか、鉄心を入れます。' },
      { lv: 2, q: 'N極をコイルに近づけると検流計の針が右にふれた。S極をコイルに近づけると、針はどちらにふれる?', a: '左', exp: '近づけることは同じで、極だけが逆になったので、電流の向きは逆になり、左にふれます。極も動かし方も逆なら右にもどります。' },
      { lv: 2, q: '電熱線Aは2Vで0.4A、電熱線Bは2Vで0.1Aの電流が流れる。AとBを直列につないで0.2Aの電流を流すには、電源の電圧を何Vにすればよい?', a: '5V', exp: 'Aは 2 ÷ 0.4 = 5Ω、Bは 2 ÷ 0.1 = 20Ω です。直列で全体は25Ωなので、電圧 = 25 × 0.2 = 5V です。' },
      { lv: 2, q: '1000Wのエアコンを1日6時間、30日間使った。電力量は何kWh?', a: '180kWh', exp: '1000W = 1kW です。1kW × 6時間 × 30日 = 180kWh。電気料金はこの kWh の量で計算されます。' },
      { lv: 3, q: '100V-60Wの電球と100V-40Wの電球を並列にして100Vの電源につなぎ、2時間使った。電源から流れる電流と、使った電力量(kWh)は?', a: '電流1A、電力量0.2kWh', exp: '並列なので、どちらも表示どおり60W・40Wで光ります。合計100Wなので、電流は 100 ÷ 100 = 1A。電力量は 0.1kW × 2時間 = 0.2kWh です。' },
      { lv: 3, q: '4Ωと12Ωの抵抗を並列にした部分に、2Ωの抵抗を直列につなぎ、10Vの電源につないだ。12Ωの抵抗に流れる電流は何A?', a: '0.5A', exp: '並列部分は 1/R = 1/4 + 1/12 = 4/12 より 3Ω。全体は5Ωで、電流は2A。並列部分の電圧は 2 × 3 = 6V なので、12Ωには 6 ÷ 12 = 0.5A(4Ωには1.5A)流れます。' },
      { lv: 3, q: '2Ωと4Ωの電熱線がある。(1) 直列につないだとき、(2) 並列につないだとき、同じ時間に発生する熱量の比(2Ω:4Ω)はそれぞれいくら?', a: '(1) 1:2 (2) 2:1', exp: '直列では電流が同じなので、電圧は抵抗に比例し、電力も抵抗に比例して1:2。並列では電圧が同じなので、電流は抵抗に反比例し、電力も2:1。つなぎ方で大小が逆になります。' },
      { lv: 3, q: '6Ωの電熱線に6Vの電圧を5分間加え、100gの水をあたためたところ、水温は3.6℃上がった。発生した熱の何%が水に伝わった?(水1gを1℃上げるのに4.2J)', a: '84%', exp: '電流は1Aで電力6W、発熱量は 6 × 300 = 1800J。水が得た熱は 4.2 × 100 × 3.6 = 1512J。1512 ÷ 1800 = 0.84 で84%です。残りは容器や空気に逃げました。' },
      { lv: 3, q: 'コイルと検流計をつないだ。誘導電流が流れないものはどれ?', choices: ['A 磁石をコイルに入れていく', 'B 磁石をコイルの中で止めておく', 'C コイルを磁石に近づける', 'D 磁石をコイルから引き出す'], a: 'B(磁石をコイルの中で止めておく)', exp: '誘導電流は、コイルの中の磁界が変化しているときだけ流れます。磁石が止まっていると磁界は変化しないので、強い磁石でも電流は流れません。' }
    ]
  });

  add('s_motion', {
    pat: [
      { name: '記録テープの打点から速さを求める', freq: 'とてもよく出る', when: '「1秒間に50回(60回)打点」「○打点ごとに切ったテープ」とあれば、この型です。', how: ['1打点の間の時間を出します(50回なら0.02秒、60回なら1/60秒)。', '「○打点ごと」の時間 = 打点の間の数 × 1打点の時間。5打点ごと(50回)なら0.1秒です。', '平均の速さ = テープの長さ ÷ その時間。', 'テープが一定の割合で長くなれば、速さが一定の割合で増える運動です。'], ex: { q: '1秒間に50回打点する記録タイマーで、10打点ごとに切ったテープの長さが8.0cmだった。平均の速さは何cm/s?', a: '40cm/s', exp: '1打点は 1 ÷ 50 = 0.02秒なので、10打点分は 0.2秒です。平均の速さは 8.0 ÷ 0.2 = 40cm/s。1秒間に50回の「50」でわってしまうまちがいに注意します。' } },
      { name: '往復・区間をまたぐ平均の速さ', freq: 'よく出る', when: '「行きは時速○km、帰りは時速○km」「全体の平均の速さ」とあれば、この型です。', how: ['速さどうしを平均してはいけません。', '区間ごとに「時間 = 距離 ÷ 速さ」を出します。', '平均の速さ = 全体の距離 ÷ 全体の時間。'], ex: { q: 'ある道のり6kmを、行きは時速12km、帰りは時速6kmで往復した。往復の平均の速さは時速何km?', a: '時速8km', exp: '行きは 6 ÷ 12 = 0.5時間、帰りは 6 ÷ 6 = 1時間。全体で12kmを1.5時間なので、12 ÷ 1.5 = 時速8km です。(12 + 6)÷ 2 = 9 とするのはまちがいです。' } },
      { name: '道具を使った仕事(仕事の原理)', freq: 'とてもよく出る', when: '「動滑車」「斜面」「てこ」を使って物体を持ち上げる問題は、この型です。', how: ['道具を使わずに真上に持ち上げたときの仕事(重さ × 高さ)を先に出します。', '道具を使っても仕事の大きさは変わらない(摩擦・道具の重さを無視)と考えます。', '動かす距離が2倍なら力は半分、のように「力 × 距離 = 仕事」から力を求めます。'], ex: { q: '重さ80Nの荷物を動滑車1つで0.5m持ち上げた。ひもを引く力と、引いた長さは?(滑車の重さと摩擦は考えない)', a: '力40N、長さ1m', exp: '直接持ち上げる仕事は 80 × 0.5 = 40J。動滑車では荷物を2本のひもで支えるので力は半分の40Nで、仕事が同じになるよう引く長さは 40 ÷ 40 = 1m です。' } },
      { name: '仕事率と効率の計算', freq: 'よく出る', when: '「○秒かけて」「仕事率」「モーター」「効率」とあれば、この型です。', how: ['仕事(J)= 力(N)× 力の向きに動いた距離(m)。', '仕事率(W)= 仕事 ÷ かかった時間(秒)。', '効率 = 役に立った仕事 ÷ 使ったエネルギー × 100(%)。'], ex: { q: '100Wのモーターで、重さ60Nの荷物を4秒間で5mの高さまで持ち上げた。このモーターの効率は何%?', a: '75%', exp: '荷物にした仕事は 60 × 5 = 300J。モーターが使った電気エネルギーは 100 × 4 = 400J。効率は 300 ÷ 400 = 0.75 で75%です。' } },
      { name: 'ふりこ・斜面の力学的エネルギー保存', freq: 'とてもよく出る', when: '「ふりこ」「ジェットコースター」「同じ高さまで上がる」「摩擦は考えない」とあれば、この型です。', how: ['位置エネルギー + 運動エネルギー = 一定、と考えます。', '最も高い点では運動エネルギーが0、最も低い点では位置エネルギーが最小で速さが最大。', '途中でくぎに糸がかかっても、はなした高さと同じ高さまで上がります。'], ex: { q: 'ふりこを高さ20cmの位置から静かにはなした。最も低い点の真上にくぎを打って糸がかかるようにすると、おもりは反対側でどこまで上がる?', a: 'はなした位置と同じ高さ20cmまで上がる。', exp: '摩擦や空気の抵抗がなければ力学的エネルギーは保存されるので、運動エネルギーが0になるのは、はじめと同じ高さです。くぎで糸の長さが変わっても高さは変わりません。' } }
    ],
    more: [
      { lv: 1, q: '900mを3分間で進んだ。速さは何m/s?', a: '5m/s', exp: '3分は180秒です。900 ÷ 180 = 5m/s。分のまま計算すると 300m/分 となり、単位がちがいます。' },
      { lv: 1, q: '時速18kmは秒速何m?', a: '5m/s', exp: '18km = 18000m、1時間 = 3600秒 なので、18000 ÷ 3600 = 5m/s。km/h の数値を3.6でわっても求められます。' },
      { lv: 1, q: '1秒間に50回打点する記録タイマーでは、となりあう打点の間の時間は何秒?', a: '0.02秒', exp: '1秒間に50回なので、1回あたり 1 ÷ 50 = 0.02秒です。5打点分なら0.1秒になります。' },
      { lv: 1, q: '走っているバスが急ブレーキをかけると、乗客は前のほうにたおれそうになる。この理由として正しいものはどれ?', choices: ['A 前向きの力が乗客にはたらくから', 'B 乗客の体が、それまでの運動を続けようとするから(慣性)', 'C バスが乗客を引っぱるから', 'D 重力が前向きになるから'], a: 'B(乗客の体が、それまでの運動を続けようとするから(慣性))', exp: 'バスが止まっても、乗客の体は慣性によって同じ速さで前に進み続けようとします。前向きの力がはたらいたわけではありません。' },
      { lv: 1, q: '重い荷物を持ったまま、その場でじっと立っていた。手が荷物にした仕事は何J?', a: '0J', exp: '仕事 = 力 × 力の向きに動いた距離 です。荷物が動いていないので距離は0で、仕事も0Jです。つかれることと、理科の仕事は別ものです。' },
      { lv: 1, q: '1Wとは、1秒間に何Jの仕事をするときの仕事率?', a: '1J', exp: '仕事率は1秒あたりの仕事で、1J/s = 1W です。100Wなら1秒間に100Jの仕事をします。' },
      { lv: 1, q: '高い所にある物体がもっているエネルギーを何という?', a: '位置エネルギー', exp: '高い所にある物体ほど、また質量が大きいほど、大きな位置エネルギーをもちます。運動している物体がもつのは運動エネルギーです。' },
      { lv: 2, q: '片道12kmの道を、行きは時速60km、帰りは時速40kmで往復した。往復の平均の速さは時速何km?', a: '時速48km', exp: '行きは 12 ÷ 60 = 0.2時間、帰りは 12 ÷ 40 = 0.3時間。24kmを0.5時間で進んだので、24 ÷ 0.5 = 時速48km。速さの平均の50とはなりません。' },
      { lv: 2, q: '1秒間に50回打点する記録タイマーで、5打点ごとに切ったテープが順に1.5cm、3.0cm、4.5cm、6.0cmだった。4本目の区間の平均の速さは何cm/s?', a: '60cm/s', exp: '5打点分は0.1秒です。4本目は 6.0 ÷ 0.1 = 60cm/s。テープが0.1秒ごとに1.5cmずつ長くなるので、速さは一定の割合で増えています。' },
      { lv: 2, q: 'てこを使い、支点から20cmの所に60Nの荷物をのせ、支点から60cmの所をおして持ち上げた。必要な力と、おした所を0.3m下げたとき荷物が上がる高さは?(てこの重さは考えない)', a: '力20N、荷物は0.1m上がる', exp: 'つりあいから 60 × 20 = F × 60 より F = 20N。距離は支点からの長さに比例するので、荷物は 0.3 × 20/60 = 0.1m 上がります。仕事は 20 × 0.3 = 60 × 0.1 = 6J で等しくなります。' },
      { lv: 2, q: '質量50kgの人が、高さ3mの階段を6秒でかけ上がった。この人がした仕事と仕事率は?(100gの物体にはたらく重力を1Nとする)', a: '仕事1500J、仕事率250W', exp: '50kgの重さは500Nです。仕事は 500 × 3 = 1500J、仕事率は 1500 ÷ 6 = 250W です。kgのまま計算しないよう注意します。' },
      { lv: 2, q: '摩擦のない斜面で台車を走らせる。斜面の傾きを大きくすると、台車の速さの増え方はどうなる?', choices: ['A 小さくなる', 'B 変わらない', 'C 大きくなる', 'D 速さが一定になる'], a: 'C(大きくなる)', exp: '傾きが大きいほど、重力の斜面にそった分力が大きくなり、速さの増え方(加速の割合)が大きくなります。真下に落ちる自由落下が最も大きい場合です。' },
      { lv: 2, q: '池にうかんだボートの上から、岸の岩を手でおした。ボートはどうなる?その理由も答えよう。', a: '岸からはなれる向きに動く。岩が手をおし返す力(反作用)を受けるから。', exp: '手が岩をおす力(作用)と同時に、岩は手を同じ大きさで反対向きにおし返します(反作用)。この力でボートは岸からはなれます。' },
      { lv: 2, q: '一定の速さでまっすぐ上昇しているエレベーターがある。エレベーターにはたらく力の合力はどうなっている?', choices: ['A 上向き', 'B 下向き', 'C 0(つりあっている)', 'D 運動の向きによって変わる'], a: 'C(0(つりあっている))', exp: '等速直線運動では、はたらく力はつりあっていて合力は0です。上に動いているから上向きの力が大きい、と考えるのはまちがいです。' },
      { lv: 2, q: '位置エネルギーと運動エネルギーの和を何という?また、摩擦があるとその和はどうなる?', a: '力学的エネルギー。摩擦があると減っていく。', exp: '摩擦や空気の抵抗がなければ力学的エネルギーは一定(保存)です。摩擦があると、一部が熱や音のエネルギーに変わり、力学的エネルギーは減ります。' },
      { lv: 3, q: '斜面を下る台車の運動を0.1秒ごとに切ったテープの長さが、順に3cm、5cm、7cm、9cmだった。次の0.1秒間のテープの長さと、その区間の平均の速さを予想しよう。', a: '11cm、110cm/s', exp: 'テープは0.1秒ごとに2cmずつ長くなっているので、次は 9 + 2 = 11cm と予想できます。平均の速さは 11 ÷ 0.1 = 110cm/s です。' },
      { lv: 3, q: '重さ80Nの荷物を、動滑車1つを使って2秒かけて0.5m持ち上げた。ひもを引く人の仕事率は何W?(滑車の重さと摩擦は考えない)', a: '20W', exp: '仕事の原理より、仕事は直接持ち上げるのと同じ 80 × 0.5 = 40J です。仕事率は 40 ÷ 2 = 20W。力は40Nで1m引きますが、仕事は変わりません。' },
      { lv: 3, q: '電力300Wのモーターで、重さ450Nの荷物を一定の速さで4m持ち上げるのに8秒かかった。モーターの効率は何%?', a: '75%', exp: '荷物にした仕事は 450 × 4 = 1800J。モーターが使った電気エネルギーは 300 × 8 = 2400J。効率は 1800 ÷ 2400 = 0.75 で75%です。' },
      { lv: 3, q: '小球を斜面の同じ高さから転がして木片に当てる実験で、小球の質量を2倍にし、転がす高さを半分にした。木片の動く距離は、もとの何倍になると考えられる?(木片の動く距離は小球のもつエネルギーに比例するとする)', a: '1倍(変わらない)', exp: '位置エネルギーは質量にも高さにも比例します。質量2倍・高さ1/2倍で 2 × 1/2 = 1倍。下で木片に当たるときのエネルギーは同じなので、動く距離も同じです。' },
      { lv: 3, q: '同じ物体の速さが2倍になると運動エネルギーは4倍になる。速さ10m/sのときの運動エネルギーが50Jの物体は、速さ30m/sのとき何Jの運動エネルギーをもつ?', a: '450J', exp: '運動エネルギーは速さの2乗に比例します。速さが3倍なので 3² = 9倍、50 × 9 = 450J です。3倍の150Jとするのはまちがいです。' }
    ]
  });

  add('s_sol', {
    pat: [
      { name: '溶解度の差で出てくる結晶の量', freq: 'とてもよく出る', when: '「○℃の飽和水溶液を△℃まで冷やす」「溶解度曲線」「出てくる結晶は何g」とあれば、この型です。', how: ['溶解度は「水100gにとける最大の量」なので、まず水の質量を確かめます。', '飽和水溶液の質量が与えられたら「水100g + 溶質(溶解度)g」の何倍かを出します。', '水100gあたりの出てくる量 =(高温の溶解度 − 低温の溶解度)。', 'それを水の量に合わせて比例させます。'], ex: { q: 'ある物質の溶解度は50℃で80g、10℃で20gである。50℃の水50gにこの物質をとけるだけとかし、10℃まで冷やすと、結晶は何g出てくる?', a: '30g', exp: '水100gなら 80 − 20 = 60g 出てきます。水は50gで半分なので、60 ÷ 2 = 30g です。水50gにとけていたのは40gで、10℃では10gしかとけない、と考えても同じです。' } },
      { name: '濃度を変える操作(うすめる・混ぜる・蒸発)', freq: 'とてもよく出る', when: '「水を加える」「水を蒸発させる」「2つの食塩水を混ぜる」とあれば、この型です。', how: ['それぞれの水溶液にとけている溶質の質量を先に出します。', '水を加える・蒸発させるときは、溶質の量は変わりません。', '混ぜるときは、溶質どうし・水溶液どうしをそれぞれ足します。', '濃度 = 溶質 ÷ 水溶液全体 × 100 で答えます。'], ex: { q: '10%の食塩水300gに水を加えて6%にしたい。水を何g加えればよい?', a: '200g', exp: '食塩は 300 × 0.1 = 30g で、水を加えても変わりません。30gで6%になる水溶液は 30 ÷ 0.06 = 500g。加える水は 500 − 300 = 200g です。' } },
      { name: '密度で物質を見分ける・浮きしずみ', freq: 'よく出る', when: '「メスシリンダーの目もりが○から△に」「何の金属か」「浮くか、しずむか」とあれば、この型です。', how: ['体積は、物体を入れる前と後のメスシリンダーの目もりの差で求めます。', '密度 = 質量 ÷ 体積。密度は物質ごとに決まった値で、大きさや形では変わりません。', '液体より密度が小さい物体は浮き、大きい物体はしずみます。'], ex: { q: '質量44.8gの金属をメスシリンダーの水に入れると、目もりが50.0cm³から55.0cm³になった。この金属は何と考えられる?(銅 8.96、鉄 7.87、アルミニウム 2.70g/cm³)', a: '銅', exp: '体積は 55.0 − 50.0 = 5.0cm³ です。密度は 44.8 ÷ 5.0 = 8.96g/cm³ で、銅の値と一致します。体積を55.0cm³と読みまちがえないことが大切です。' } },
      { name: '気体の発生方法・集め方・確かめ方', freq: 'とてもよく出る', when: '「○○に△△を加えると発生する気体」「集め方」「確かめる方法」の組み合わせを問う問題は、この型です。', how: ['発生方法から気体を決めます(例:石灰石+塩酸 → 二酸化炭素)。', '水にとけにくい → 水上置換法。とけやすく空気より軽い → 上方置換法、重い → 下方置換法。', '確かめ方(石灰水・線香・マッチの火・におい・色)を気体ごとに対応させます。'], ex: { q: '石灰石にうすい塩酸を加えると発生する気体は何?また、その確かめ方は?', a: '二酸化炭素。石灰水に通すと白くにごる。', exp: '石灰石の主成分は炭酸カルシウムで、塩酸と反応して二酸化炭素が出ます。二酸化炭素は水に少しとけ、空気より重いので、水上置換法か下方置換法で集めます。' } },
      { name: '混合物の加熱(蒸留)と温度のグラフ', freq: 'よく出る', when: '「水とエタノールの混合物を加熱」「試験管に順に集める」「温度が一定にならない」とあれば、この型です。', how: ['純物質は沸点で温度が一定になり、混合物はならない(ゆるやかに上がる)と考えます。', '沸点の低い物質(エタノール約78℃)が先に多く出てきます。', '集めた液体は、においをかぐ・火をつけるなどで、エタノールが多いか確かめます。'], ex: { q: '水とエタノールの混合物を加熱し、出てきた液体を3本の試験管に順に集めた。エタノールを最も多くふくむのは何本目?', a: '1本目', exp: 'エタノールの沸点(約78℃)は水(100℃)より低いので、はじめのほうに多く出てきます。1本目の液体はにおいが強く、火をつけると燃えます。' } }
    ],
    more: [
      { lv: 1, q: '有機物はどれ?', choices: ['A 食塩', 'B 鉄', 'C 砂糖', 'D ガラス'], a: 'C(砂糖)', exp: '有機物は炭素をふくむ物質で、燃やすと二酸化炭素ができます。砂糖は燃やすとこげて二酸化炭素が出ます。食塩・鉄・ガラスは無機物です。' },
      { lv: 1, q: '質量27g、体積10cm³の物質の密度は何g/cm³?', a: '2.7g/cm³', exp: '密度 = 質量 ÷ 体積 = 27 ÷ 10 = 2.7g/cm³ です。この値はアルミニウムの密度と同じです。' },
      { lv: 1, q: '二酸化マンガンに何を加えると酸素が発生する?', a: 'うすい過酸化水素水(オキシドール)', exp: '二酸化マンガンは、過酸化水素が分解するのを助けるだけで、自分は変化しません。発生した酸素は水上置換法で集めます。' },
      { lv: 1, q: '気体が二酸化炭素であることを確かめるには、どうすればよい?', a: '石灰水に通す(石灰水が白くにごる)。', exp: '二酸化炭素は石灰水を白くにごらせます。火のついた線香を入れると、火が消えることからも見当がつきますが、確かめには石灰水を使います。' },
      { lv: 1, q: '固体がとけて液体になるときの温度を何という?', a: '融点', exp: '固体が液体になる温度が融点、液体が沸騰して気体になる温度が沸点です。純物質では、融点や沸点は物質ごとに決まっています。' },
      { lv: 1, q: '食塩水で、食塩のようにとけている物質を溶質という。水のようにとかしている液体を何という?', a: '溶媒', exp: 'とけている物質が溶質、とかしている液体が溶媒、両方を合わせたものが溶液です。溶媒が水の溶液を水溶液といいます。' },
      { lv: 1, q: '液体を加熱して出てきた気体を冷やし、再び液体にしてとり出す方法を何という?', a: '蒸留', exp: '蒸留は、沸点のちがいを利用して混合物から物質を分ける方法です。水とエタノールの混合物を分けるときなどに使います。' },
      { lv: 2, q: '質量23.7gの金属をメスシリンダーの水に入れると、目もりが50.0cm³から53.0cm³になった。密度は何g/cm³?また、何の金属と考えられる?(鉄 7.9、アルミニウム 2.7、銅 9.0g/cm³)', a: '7.9g/cm³、鉄', exp: '体積は目もりの差で 53.0 − 50.0 = 3.0cm³。密度は 23.7 ÷ 3.0 = 7.9g/cm³ で、鉄と考えられます。' },
      { lv: 2, q: '5%の食塩水400gには、食塩と水がそれぞれ何gふくまれている?', a: '食塩20g、水380g', exp: '食塩は 400 × 0.05 = 20g です。水は全体から食塩を引いて 400 − 20 = 380g。水の量を400gとしないよう注意します。' },
      { lv: 2, q: '食塩40gをすべて使って、8%の食塩水をつくりたい。水は何g必要?', a: '460g', exp: '8%で食塩が40gなら、食塩水全体は 40 ÷ 0.08 = 500g です。水は 500 − 40 = 460g。500gと答えるまちがいに注意します。' },
      { lv: 2, q: '水素を集めるのに最も適した方法はどれ?', choices: ['A 水上置換法', 'B 上方置換法', 'C 下方置換法', 'D どれでも同じ'], a: 'A(水上置換法)', exp: '水素は水にとけにくいので水上置換法で集めます。水上置換法は空気が混ざりにくく、集めた量も見やすいので、水にとけにくい気体ではこれを選びます。' },
      { lv: 2, q: 'とかしたロウをビーカーに入れて冷やすと、固体になり、中央がへこんだ。このとき、ロウの質量と密度はどうなった?', a: '質量は変わらず、密度は大きくなった。', exp: '状態変化では粒子の数は変わらないので質量は同じです。中央がへこんだのは体積が小さくなったからで、密度 = 質量 ÷ 体積 は大きくなります。' },
      { lv: 2, q: '純物質と混合物を加熱したときの温度変化について、正しいものはどれ?', choices: ['A どちらも沸騰中は温度が一定', 'B 純物質は沸騰中の温度が一定で、混合物は一定にならない', 'C 混合物だけ沸騰中の温度が一定', 'D どちらも沸騰中に温度が下がる'], a: 'B(純物質は沸騰中の温度が一定で、混合物は一定にならない)', exp: '純物質は沸点で、加えた熱が状態変化に使われるので温度が止まります。混合物は成分の割合が変わっていくので、温度が少しずつ上がり続けます。' },
      { lv: 2, q: 'ある物質の40℃での溶解度は64gである。40℃の水50gには、この物質を最大何gとかすことができる?', a: '32g', exp: '溶解度は水100gあたりの量です。水50gでは半分の 64 ÷ 2 = 32g までとけます。' },
      { lv: 2, q: '再結晶で出てきた結晶を、ろ過でとり出す。ろ過のしかたとして正しくないものはどれ?', choices: ['A 液はガラス棒を伝わらせて注ぐ', 'B ろうとの先の長いほうをビーカーのかべにつける', 'C ろ紙は水でぬらしてろうとにつける', 'D 液はろ紙からあふれるくらい一度に注ぐ'], a: 'D(液はろ紙からあふれるくらい一度に注ぐ)', exp: 'ろ紙からあふれると、結晶がろ紙とろうとのすき間から流れ出てしまいます。液はガラス棒を伝わらせて、ろ紙の8分目くらいまでに少しずつ注ぎます。' },
      { lv: 3, q: 'ある物質の溶解度は50℃で80g、10℃で20gである。50℃のこの物質の飽和水溶液270gを10℃まで冷やすと、結晶は何g出てくる?', a: '90g', exp: '50℃の飽和水溶液は「水100g+物質80g = 180g」の割合です。270gは1.5倍なので、水150g・物質120g。10℃では水150gに 20 × 1.5 = 30g しかとけず、120 − 30 = 90g 出てきます。' },
      { lv: 3, q: '15%の食塩水200gと5%の食塩水300gを混ぜた。何%の食塩水になる?', a: '9%', exp: '食塩は 200 × 0.15 = 30g と 300 × 0.05 = 15g で、合計45g。全体は500gなので、45 ÷ 500 = 0.09 で9%です。15と5の平均の10%ではありません。' },
      { lv: 3, q: '12%の食塩水250gを加熱して水を蒸発させ、20%にしたい。水を何g蒸発させればよい?', a: '100g', exp: '食塩は 250 × 0.12 = 30g で、蒸発させても変わりません。30gで20%になる食塩水は 30 ÷ 0.2 = 150g。蒸発させる水は 250 − 150 = 100g です。' },
      { lv: 3, q: '水(1.0g/cm³)には浮き、エタノール(0.79g/cm³)にはしずむプラスチックの密度として考えられるのはどれ?', choices: ['A 0.70g/cm³', 'B 0.90g/cm³', 'C 1.05g/cm³', 'D 1.40g/cm³'], a: 'B(0.90g/cm³)', exp: '水に浮くので1.0より小さく、エタノールにしずむので0.79より大きい必要があります。この条件を満たすのは0.90g/cm³だけです(ポリプロピレンなど)。' },
      { lv: 3, q: '富士山の山頂では、水が100℃より低い温度(約87℃)で沸騰する。その理由として正しいものはどれ?', choices: ['A 山頂は気温が低いから', 'B 山頂は気圧が低く、沸点が下がるから', 'C 山頂の水は純粋だから', 'D 山頂では水の密度が大きいから'], a: 'B(山頂は気圧が低く、沸点が下がるから)', exp: '沸点はまわりの気圧で変わり、気圧が低いほど低くなります。山頂ではお湯の温度が上がりきらないので、ご飯がうまくたけないことがあります。' }
    ]
  });

  add('s_m2', {
    pat: [
      { name: '結びつく質量の比(酸化)', freq: 'とてもよく出る', when: '「金属○gを完全に酸化させると」「グラフから質量の比」とあれば、この型です。', how: ['グラフや表から「金属:酸素:酸化物」の質量の比を出します(銅 4:1:5、マグネシウム 3:2:5)。', '分かっている量を比の1つにあてはめ、比例で他の量を求めます。', '酸素の質量 = 加熱後の質量 − 加熱前の質量 です。'], ex: { q: '銅2.8gを完全に酸化させると、酸化銅は何gできる?(銅:酸素 = 4:1)', a: '3.5g', exp: '銅:酸化銅 = 4:5 です。2.8 × 5/4 = 3.5g。結びついた酸素は 3.5 − 2.8 = 0.7g で、2.8:0.7 = 4:1 になっていることも確かめられます。' } },
      { name: '加熱が不十分なとき「まだ反応していない量」', freq: 'とてもよく出る', when: '「途中で加熱をやめた」「質量は○gだった」「まだ反応していない銅(マグネシウム)は何g」とあれば、この型です。', how: ['増えた質量 = 結びついた酸素の質量 と考えます。', '酸素の質量から、比を使って「反応した金属の質量」を求めます。', 'はじめの金属 − 反応した金属 = まだ反応していない金属。'], ex: { q: 'マグネシウム1.2gを加熱し、途中でやめると質量は1.6gだった。まだ酸素と結びついていないマグネシウムは何g?(マグネシウム:酸素 = 3:2)', a: '0.6g', exp: '結びついた酸素は 1.6 − 1.2 = 0.4g です。反応したマグネシウムは 0.4 × 3/2 = 0.6g なので、残りは 1.2 − 0.6 = 0.6g です。' } },
      { name: '酸化銅の還元と過不足', freq: 'よく出る', when: '「酸化銅と炭素の粉末を混ぜて加熱」「銅は何g」「炭素は何g必要」とあれば、この型です。', how: ['酸化銅の質量から、銅と酸素の質量を 4:1 で分けます。', 'うばわれた酸素と炭素が結びついて二酸化炭素になります(炭素:酸素 = 3:8)。', '炭素が多すぎるときは、余った炭素が試験管に残ることに注意します。'], ex: { q: '酸化銅10.0gを炭素で完全に還元した。できた銅と、必要な炭素はそれぞれ何g?(銅:酸素 = 4:1、炭素:酸素 = 3:8)', a: '銅8.0g、炭素0.75g', exp: '酸化銅10.0gは銅8.0gと酸素2.0gに分けられます。酸素2.0gと結びつく炭素は 2.0 × 3/8 = 0.75g です。発生する二酸化炭素は 2.75g になります。' } },
      { name: '化学反応式の係数あわせ', freq: 'とてもよく出る', when: '「化学反応式で表しなさい」とあれば、この型です。', how: ['矢印の左に反応前、右に反応後の物質の化学式を書きます(化学式は変えない)。', '左右で原子の数が少ない種類から、係数をつけて数をそろえます。', '最後に、すべての原子の数が左右で等しいかを数えて確かめます。'], ex: { q: '水素が燃えて水ができる反応を、化学反応式で表そう。', a: '2H₂ + O₂ → 2H₂O', exp: 'H₂ + O₂ → H₂O では酸素原子が左2個・右1個です。右を2H₂Oにすると水素原子が右4個になるので、左を2H₂にします。H は4個・O は2個でそろいます。' } },
      { name: '質量保存の法則(ふたを開けるか閉めるか)', freq: 'よく出る', when: '「密閉した容器」「ふたを開けると」「反応前後の質量」とあれば、この型です。', how: ['化学変化の前後で、原子の種類と数は変わらないので、全体の質量は変わりません。', '気体が出入りできる容器では、出ていった気体(入ってきた酸素)の分だけ質量が変わります。', '沈殿ができても、すべてが容器の中にあれば質量は変わりません。'], ex: { q: '密閉した容器の中で石灰石とうすい塩酸を反応させた。反応後、ふたを開けると全体の質量はどうなる?', a: '減る。', exp: '密閉したままなら、発生した二酸化炭素も容器内にあるので質量は変わりません。ふたを開けると二酸化炭素が空気中に出ていくので、その分だけ質量が減ります。' } }
    ],
    more: [
      { lv: 1, q: '化学変化はどれ?', choices: ['A 氷がとける', 'B ろうそくが燃える', 'C 砂糖が水にとける', 'D 水が蒸発する'], a: 'B(ろうそくが燃える)', exp: 'ろうそくが燃えると、二酸化炭素や水という別の物質ができるので化学変化です。ほかの3つは、物質そのものは変わらない状態変化や溶解です。' },
      { lv: 1, q: '酸素分子の化学式を書こう。', a: 'O₂', exp: '酸素は酸素原子2個が結びついた分子として存在するので O₂ です。原子1個を表す O と区別します。' },
      { lv: 1, q: '物質が酸素と結びつく化学変化を何という?また、そのうち熱や光を激しく出すものを何という?', a: '酸化、燃焼', exp: '酸化のうち、熱や光を出しながら激しく進むものを燃焼といいます。鉄がゆっくりさびるのは、燃焼ではない酸化です。' },
      { lv: 1, q: '酸化物から酸素をとり除く化学変化を何という?', a: '還元', exp: '酸化銅と炭素を混ぜて加熱すると、炭素が酸素をうばって銅がとり出せます。このとき、還元と酸化は同時に起こっています。' },
      { lv: 1, q: '炭酸水素ナトリウムを加熱したとき、試験管の口にできた液体が水であることは、何を使って確かめる?', a: '塩化コバルト紙(青色が赤色(桃色)に変わる)', exp: '青色の塩化コバルト紙は、水にふれると赤色(桃色)に変わります。この性質を使って、できた液体が水だと確かめます。' },
      { lv: 1, q: '単体はどれ?', choices: ['A 水', 'B 二酸化炭素', 'C 銅', 'D 塩化ナトリウム'], a: 'C(銅)', exp: '1種類の元素だけでできた物質が単体、2種類以上の元素でできた物質が化合物です。銅は Cu だけでできているので単体です。' },
      { lv: 1, q: '化学反応式で、矢印の左側と右側で必ず等しくなっているものは?', a: '原子の種類と数', exp: '化学変化では、原子の組み合わせが変わるだけで、原子がなくなったり新しくできたりはしません。だから左右の原子の種類と数は等しくなります。' },
      { lv: 2, q: 'マグネシウム1.5gを完全に酸化させると、酸化マグネシウムは何gできる?(マグネシウム:酸素 = 3:2)', a: '2.5g', exp: 'マグネシウム:酸化マグネシウム = 3:5 なので、1.5 × 5/3 = 2.5g です。結びついた酸素は1.0gです。' },
      { lv: 2, q: '酸化銅5.0gをつくるには、銅が何g必要?(銅:酸素 = 4:1)', a: '4.0g', exp: '銅:酸化銅 = 4:5 なので、銅 = 5.0 × 4/5 = 4.0g です。酸素は1.0g結びつきます。' },
      { lv: 2, q: '鉄と硫黄は質量の比7:4で過不足なく反応する。鉄21gと過不足なく反応する硫黄は何g?また、硫化鉄は何gできる?', a: '硫黄12g、硫化鉄33g', exp: '鉄21gは7の3倍なので、硫黄も4の3倍で12gです。できる硫化鉄は 21 + 12 = 33g(質量保存の法則)です。' },
      { lv: 2, q: '銅が酸素と結びついて酸化銅(CuO)ができる反応を、化学反応式で表そう。', a: '2Cu + O₂ → 2CuO', exp: 'Cu + O₂ → CuO では酸素原子が左2個・右1個です。右を2CuOにすると銅原子が2個になるので、左を2Cuにします。' },
      { lv: 2, q: '水の電気分解を、化学反応式で表そう。', a: '2H₂O → 2H₂ + O₂', exp: 'H₂O → H₂ + O₂ では酸素原子が左1個・右2個です。左を2H₂Oにすると水素原子が4個になるので、右を2H₂にします。体積の比 水素:酸素 = 2:1 は係数の比と同じです。' },
      { lv: 2, q: 'うすい硫酸とうすい水酸化バリウム水溶液を、容器の中で混ぜると白い沈殿ができた。反応の前後で全体の質量はどうなる?', a: '変わらない。', exp: '沈殿ができても、気体として出ていくものはなく、すべての原子が容器の中に残っています。したがって質量保存の法則どおり、全体の質量は変わりません。' },
      { lv: 2, q: '加熱をやめても、反応で出る熱によって反応が続くものはどれ?', choices: ['A 鉄粉と硫黄の粉末の混合物を加熱する', 'B 炭酸水素ナトリウムを加熱する', 'C 酸化銀を加熱する', 'D 水を電気分解する'], a: 'A(鉄粉と硫黄の粉末の混合物を加熱する)', exp: '鉄と硫黄の反応は大きな熱を出す発熱反応で、一部を加熱すると、その熱で反応が全体に広がります。B・Cの分解は加熱し続けないと止まります。' },
      { lv: 2, q: '酸化銅と炭素の混合物を加熱し、発生した気体を石灰水に通した。加熱をやめる前に、まず何をする?また、その理由は?', a: 'ガラス管を石灰水からぬく。石灰水が逆流して試験管が割れるのを防ぐため。', exp: '先に火を消すと、試験管の中の気体が冷えて縮み、石灰水が吸いこまれて熱い試験管に流れこみます。そのあと、ゴム管をピンチコックで閉じて空気が入らないようにします。' },
      { lv: 3, q: '銅の粉末2.0gを加熱し、途中で加熱をやめると質量は2.3gだった。まだ酸素と結びついていない銅は何g?(銅:酸素 = 4:1)', a: '0.8g', exp: '結びついた酸素は 2.3 − 2.0 = 0.3g です。反応した銅は 0.3 × 4 = 1.2g なので、残りは 2.0 − 1.2 = 0.8g です。' },
      { lv: 3, q: '酸化銅4.0gと炭素0.6gを混ぜて加熱し、反応を完全に終わらせた。試験管に残った固体の質量は何g?(銅:酸素 = 4:1、炭素:酸素 = 3:8)', a: '3.5g', exp: '酸化銅4.0gは銅3.2g・酸素0.8g。酸素0.8gと結びつく炭素は 0.8 × 3/8 = 0.3g なので、炭素は 0.6 − 0.3 = 0.3g 余ります。残る固体は 銅3.2g + 炭素0.3g = 3.5g です。' },
      { lv: 3, q: '銅とマグネシウムの混合物5.0gを完全に酸化させると、7.5gになった。混合物中の銅とマグネシウムはそれぞれ何g?(銅:酸化銅 = 4:5、マグネシウム:酸化マグネシウム = 3:5)', a: '銅2.0g、マグネシウム3.0g', exp: '銅を x g とすると、マグネシウムは(5.0 − x)g。1.25x + (5/3)(5.0 − x) = 7.5 を解くと x = 2.0。確かめ:酸化銅2.5g + 酸化マグネシウム5.0g = 7.5g です。' },
      { lv: 3, q: '炭酸水素ナトリウム(NaHCO₃)を加熱すると、炭酸ナトリウム(Na₂CO₃)と水と二酸化炭素に分解する。この化学反応式を書こう。', a: '2NaHCO₃ → Na₂CO₃ + H₂O + CO₂', exp: '右のNa₂CO₃にNaが2個あるので、左を2NaHCO₃にします。すると左はNa2・H2・C2・O6。右はNa2・C1+1・O3+1+2・H2 で、すべてそろいます。' },
      { lv: 3, q: '銅の質量を0.4g、0.8g、1.2gと変えて完全に酸化させると、酸化銅の質量はそれぞれ0.5g、1.0g、1.5gだった。酸素1.0gと結びつく銅は何g?', a: '4.0g', exp: '結びついた酸素は 0.1g、0.2g、0.3g で、銅:酸素 = 4:1 と分かります。酸素1.0gと結びつく銅は 1.0 × 4 = 4.0g です。' }
    ]
  });

  add('s_ion', {
    pat: [
      { name: '原子・イオンの電子の数', freq: 'よく出る', when: '「イオンの化学式」「電子を何個失った(受けとった)」「陽子と電子の数」とあれば、この型です。', how: ['原子では、陽子の数 = 電子の数 で電気的に中性です。', '電子を失うと陽イオン(+)、受けとると陰イオン(−)になります。', '右上の数字は、失った(受けとった)電子の数を表します。'], ex: { q: 'マグネシウム原子(電子12個)がマグネシウムイオン Mg²⁺ になると、電子は何個になる?', a: '10個', exp: 'Mg²⁺ は電子を2個失って+の電気を2つもつイオンです。12 − 2 = 10個。陽子の数12個は変わらないので、全体として+2になります。' } },
      { name: '電気分解で何ができるか', freq: 'とてもよく出る', when: '「塩化銅水溶液」「塩酸」を電気分解し、陰極・陽極にできる物質を問う問題は、この型です。', how: ['水溶液中の陽イオンと陰イオンを書き出します(CuCl₂ → Cu²⁺ + 2Cl⁻)。', '陽イオンは陰極に引かれて電子を受けとり、原子になります(銅・水素)。', '陰イオンは陽極に引かれて電子をわたし、気体などになります(塩素)。'], ex: { q: 'うすい塩酸を電気分解すると、陰極にできる気体は何?', a: '水素', exp: '塩酸は HCl → H⁺ + Cl⁻ と電離しています。+の水素イオンが陰極で電子を受けとって水素になります。陽極では塩化物イオンが塩素になります。' } },
      { name: '中和とイオンの数のグラフ', freq: 'とてもよく出る', when: '「塩酸に水酸化ナトリウム水溶液を加えていく」「イオンの数の変化を表すグラフ」とあれば、この型です。', how: ['加える前のイオン(H⁺・Cl⁻)と、加える液のイオン(Na⁺・OH⁻)を書き出します。', 'H⁺ と OH⁻ は結びついて水になるので、中和が終わるまで OH⁻ は増えず、H⁺ は減ります。', '反応しないイオン(Cl⁻ は一定、Na⁺ は増え続ける)を区別します。', 'ちょうど中和した点の後は、OH⁻ が増え始めます。'], ex: { q: 'うすい塩酸に水酸化ナトリウム水溶液を少しずつ加えた。加えた量に関係なく、数が一定のイオンは何?', a: '塩化物イオン Cl⁻', exp: 'Cl⁻ は反応せず、液に加えられることもないので一定です。H⁺ は減って中和点で0、Na⁺ は増え続け、OH⁻ は中和点のあとから増えます。' } },
      { name: '中和に必要な体積の比', freq: 'とてもよく出る', when: '「ちょうど中和する」「同じ塩酸を○cm³にすると」「濃度を2倍にすると」とあれば、この型です。', how: ['ちょうど中和する体積の比を、基準として書きます。', '酸の量が何倍になったかを考え、アルカリも同じ倍率にします。', '濃度が2倍なら、同じ体積でも2倍の量の H⁺(OH⁻)をふくみます。'], ex: { q: 'うすい塩酸10cm³は水酸化ナトリウム水溶液15cm³でちょうど中和する。この塩酸30cm³をちょうど中和するのに必要な水酸化ナトリウム水溶液は何cm³?', a: '45cm³', exp: '塩酸が3倍になったので、必要な水酸化ナトリウム水溶液も3倍の 15 × 3 = 45cm³ です。体積の比 塩酸:水酸化ナトリウム水溶液 = 2:3 は変わりません。' } },
      { name: '電池の条件と−極の判断', freq: 'よく出る', when: '「2種類の金属板」「電解質の水溶液」「−極はどちら」「電子の流れる向き」とあれば、この型です。', how: ['電池になる条件:2種類の異なる金属 + 電解質の水溶液 + 導線でつなぐ。', 'イオンになりやすい金属が電子を出して溶け、−極になります。', '電子は導線を −極 → +極へ、電流はその逆向きに流れます。'], ex: { q: '亜鉛板と銅板をうすい塩酸に入れて導線でつないだ。−極はどちらで、電子は導線をどちら向きに流れる?', a: '−極は亜鉛板。電子は亜鉛板から銅板へ流れる。', exp: '亜鉛のほうが銅よりイオンになりやすいので、亜鉛原子が電子を出して Zn²⁺ になってとけ出します。その電子が導線を通って銅板へ流れるので、亜鉛板が−極です。' } }
    ],
    more: [
      { lv: 1, q: '原子核をつくる粒子のうち、電気をもたない粒子は何?', a: '中性子', exp: '原子核は、+の電気をもつ陽子と、電気をもたない中性子でできています。そのまわりに−の電気をもつ電子があります。' },
      { lv: 1, q: 'マグネシウムイオンを化学式で表そう。(マグネシウム原子は電子を2個失う)', a: 'Mg²⁺', exp: '電子を2個失うと+の電気を2つもつので、右上に2+をつけて Mg²⁺ と書きます。1個のときは Na⁺ のように数字を省きます。' },
      { lv: 1, q: '電解質はどれ?', choices: ['A 砂糖', 'B エタノール', 'C 塩化ナトリウム', 'D ブドウ糖'], a: 'C(塩化ナトリウム)', exp: '水にとけて陽イオンと陰イオンに分かれる(電離する)物質が電解質で、その水溶液は電流を通します。砂糖・エタノール・ブドウ糖は電離しない非電解質です。' },
      { lv: 1, q: 'BTB溶液は、アルカリ性の水溶液に入れると何色になる?', a: '青色', exp: 'BTB溶液は、酸性で黄色、中性で緑色、アルカリ性で青色になります。' },
      { lv: 1, q: '中和で、水素イオンと水酸化物イオンが結びつく変化を式で表そう。', a: 'H⁺ + OH⁻ → H₂O', exp: '中和では、酸の H⁺ とアルカリの OH⁻ が結びついて水ができ、たがいの性質を打ち消し合います。同時に、残りのイオンから塩ができます。' },
      { lv: 1, q: '物質がもつ化学エネルギーを、電気エネルギーに変えてとり出す装置を何という?', a: '電池(化学電池)', exp: '電池では、金属がイオンになるときに出す電子を導線に流して、電気エネルギーとしてとり出します。' },
      { lv: 1, q: 'フェノールフタレイン溶液は、アルカリ性の水溶液に入れると何色になる?', a: '赤色', exp: 'フェノールフタレイン溶液は、アルカリ性で赤色になり、酸性・中性では無色です。酸性か中性かの区別には使えません。' },
      { lv: 2, q: '塩化ナトリウムの電離を、式で表そう。', a: 'NaCl → Na⁺ + Cl⁻', exp: '塩化ナトリウムは水にとけると、ナトリウムイオンと塩化物イオンに分かれます。陽イオンと陰イオンの電気の量は、つり合っています。' },
      { lv: 2, q: '塩化銅(CuCl₂)の電離を、式で表そう。', a: 'CuCl₂ → Cu²⁺ + 2Cl⁻', exp: '銅イオンは+2、塩化物イオンは−1なので、銅イオン1個に対して塩化物イオンが2個できます。+2と−1×2で電気がつり合います。' },
      { lv: 2, q: '塩化銅水溶液を電気分解したとき、陽極付近の液をとって赤インクで色をつけた水に加えると、色が消えた。この理由は?', a: '陽極で塩素が発生し、塩素には漂白作用があるから。', exp: '陽極では塩化物イオンが電子をわたして塩素になります。塩素は水にとけやすく、漂白作用やプールのような特有のにおいがあります。' },
      { lv: 2, q: 'うすい塩酸12cm³は水酸化ナトリウム水溶液8cm³でちょうど中和する。この塩酸18cm³をちょうど中和するのに必要な水酸化ナトリウム水溶液は何cm³?', a: '12cm³', exp: '体積の比は 塩酸:水酸化ナトリウム水溶液 = 12:8 = 3:2 です。塩酸18cm³なら、18 × 2/3 = 12cm³ です。' },
      { lv: 2, q: '塩酸と水酸化ナトリウム水溶液をちょうど中和させた液を蒸発させると、白い結晶が残った。この物質は何?', a: '塩化ナトリウム', exp: '酸の陰イオン Cl⁻ とアルカリの陽イオン Na⁺ が結びついた物質(塩)が塩化ナトリウムです。HCl + NaOH → NaCl + H₂O。' },
      { lv: 2, q: '電子オルゴールが鳴る(電池になる)組み合わせはどれ?', choices: ['A 亜鉛板と銅板を砂糖水に入れる', 'B 亜鉛板と銅板を食塩水に入れる', 'C 銅板2枚を食塩水に入れる', 'D 亜鉛板と銅板をエタノールに入れる'], a: 'B(亜鉛板と銅板を食塩水に入れる)', exp: '電池には、2種類の異なる金属と電解質の水溶液が必要です。砂糖水やエタノールは非電解質、Cは同じ金属なので電池になりません。' },
      { lv: 2, q: 'ダニエル電池で、−極になるのは亜鉛板・銅板のどちら?また、導線を電子が流れる向きは?', a: '−極は亜鉛板。電子は亜鉛板から銅板へ流れる。', exp: '亜鉛のほうがイオンになりやすく、亜鉛原子が電子を出して Zn²⁺ になります。その電子が導線を通って銅板へ流れ、銅板では Cu²⁺ が電子を受けとって銅になります。' },
      { lv: 2, q: 'pH3の水溶液とpH5の水溶液では、酸性が強いのはどちら?', a: 'pH3の水溶液', exp: 'pHは7が中性で、7より小さいほど酸性が強くなります。7より大きいほどアルカリ性が強くなります。' },
      { lv: 3, q: '水素イオンが10個、塩化物イオンが10個ふくまれる塩酸に、1cm³あたりナトリウムイオンと水酸化物イオンを2個ずつふくむ水酸化ナトリウム水溶液を8cm³加えた。液中の水酸化物イオンとナトリウムイオンはそれぞれ何個?', a: '水酸化物イオン6個、ナトリウムイオン16個', exp: '加えた OH⁻ は16個で、そのうち10個が H⁺ 10個と水になります。残る OH⁻ は6個です。Na⁺ は反応しないので16個。Cl⁻ は10個のままです。' },
      { lv: 3, q: 'うすい塩酸に電極を入れ、水酸化ナトリウム水溶液を少しずつ加えた。ちょうど中和したとき、電流は流れる?その理由は?', a: '流れる。中和でできた塩化ナトリウムが水溶液中で電離しているから。', exp: '中和点では H⁺ も OH⁻ も残りませんが、Na⁺ と Cl⁻ がイオンのまま液中にあるので電流が流れます。硫酸と水酸化バリウムの場合は、塩が沈殿するので中和点で電流がほぼ0になります。' },
      { lv: 3, q: 'イオンへのなりやすさは Mg > Zn > Cu である。次のうち、金属の表面に変化が起こらないものはどれ?', choices: ['A 硫酸銅水溶液に亜鉛板', 'B 硫酸銅水溶液にマグネシウム板', 'C 硫酸亜鉛水溶液にマグネシウム板', 'D 硫酸マグネシウム水溶液に銅板'], a: 'D(硫酸マグネシウム水溶液に銅板)', exp: '金属が、水溶液中のイオンの金属よりイオンになりやすいときだけ反応します。銅はマグネシウムよりイオンになりにくいので、変化しません。' },
      { lv: 3, q: '塩化銅水溶液を電気分解し、陰極に銅原子が30個付着した。このとき、陽極で発生した塩素分子は何個?', a: '30個', exp: '銅イオン1個が銅原子になるには電子2個が必要なので、流れた電子は60個です。塩化物イオン2個が電子2個をわたして塩素分子1個になるので、60 ÷ 2 = 30個です。' },
      { lv: 3, q: '塩素原子は電子を17個もつ。塩化物イオン Cl⁻ がもつ電子と陽子の数はそれぞれ何個?', a: '電子18個、陽子17個', exp: '塩素原子が電子を1個受けとると Cl⁻ になるので、電子は18個です。陽子の数は原子の種類で決まり、17個のままです。電子が1個多い分、全体で−1になります。' }
    ]
  });

  add('sx_jh', {
    pat: [
      { name: '単位をそろえてから公式に入れる', freq: 'とてもよく出る', when: '問題文に cm²・分・mA・kW・g など、公式の単位(m²・秒・A・W・N)とちがう単位があれば、この型です。', how: ['公式に必要な単位を先に書き出します(圧力なら N と m²)。', '問題の数値をすべてその単位に直します(1cm² = 0.0001m²、1分 = 60秒、1mA = 0.001A)。', '計算したあと、答えの単位が求める量の単位になっているか確かめます。'], ex: { q: '重さ6Nの物体を、面積15cm²の面を下にして置いた。床が受ける圧力は何Pa?', a: '4000Pa', exp: '15cm² = 0.0015m² です。圧力 = 6 ÷ 0.0015 = 4000Pa。cm² のまま 6 ÷ 15 = 0.4 とすると、単位が N/cm² になってしまいます。' } },
      { name: '「何が一定か」を見ぬいて比で解く', freq: 'とてもよく出る', when: '「同じ電熱線で」「水の量を2倍にして」など、条件を変えて比べる問題は、この型です。', how: ['変えていない条件(電熱線・電圧など)を確認します。', '求める量が、変えた量に比例するのか反比例するのかを決めます(上昇温度は時間に比例、水の量に反比例)。', '倍率をかけ合わせて答えを出します。'], ex: { q: 'ある電熱線で水100gを4分間温めると5℃上がった。同じ電熱線で水200gを12分間温めると何℃上がる?(熱はすべて水に伝わる)', a: '7.5℃', exp: '時間が3倍なので熱量は3倍、水が2倍なので上昇温度は1/2倍です。5 × 3 × 1/2 = 7.5℃。1つずつ倍率をかけると、公式を使わなくても解けます。' } },
      { name: '熱効率(何%が水に伝わったか)', freq: 'よく出る', when: '「発生した熱の○%が水に伝わる」「何%が水に伝わったか」とあれば、この型です。', how: ['発生した熱量 = 電力 × 時間(秒)。', '水が得た熱量 = 4.2 × 水の質量 × 上昇温度。', '効率 = 水が得た熱量 ÷ 発生した熱量 × 100。'], ex: { q: '800Wの電気ケトルで水400gを20℃から80℃まで温めるのに2分30秒かかった。発生した熱の何%が水に伝わった?(水1gを1℃上げるのに4.2J)', a: '84%', exp: '発生した熱は 800 × 150 = 120000J。水が得た熱は 4.2 × 400 × 60 = 100800J。100800 ÷ 120000 = 0.84 で84%です。' } },
      { name: '濃度は「溶質の質量」で式をつくる', freq: 'とてもよく出る', when: '「混ぜる」「溶質を加える」「水を蒸発させる」など、濃度が変わる問題は、この型です。', how: ['それぞれの水溶液の溶質の質量を出します。', '操作のあとの溶質と水溶液全体の質量をそれぞれ式にします。', '求める量を x とおき、溶質 = 全体 × 濃度 で方程式をつくります。'], ex: { q: '15%の食塩水200gに食塩を加えて20%にしたい。食塩を何g加えればよい?', a: '12.5g', exp: '加える量を x g とすると、食塩は(30 + x)g、全体は(200 + x)g。30 + x = 0.2(200 + x)より 0.8x = 10、x = 12.5g。全体の質量も増えることに注意します。' } },
      { name: 'グラフの傾き・切片の意味', freq: 'よく出る', when: '「グラフは直線になった」「加熱を始める前の水温」「傾きは何を表すか」とあれば、この型です。', how: ['横軸と縦軸の量を確かめ、傾き =(縦の変化)÷(横の変化)の意味を言葉にします。', '水温−時間なら傾きは「1分あたりの上昇温度」、切片は「はじめの水温」。', '条件を変えたとき、傾きと切片のどちらが変わるかを考えます。'], ex: { q: '電熱線で水を温めると、水温は「1分ごとに2℃」の割合で上がり、5分後に30℃だった。加熱を始める前の水温は何℃?', a: '20℃', exp: '5分間で 2 × 5 = 10℃ 上がったので、はじめは 30 − 10 = 20℃。これはグラフの切片にあたります。傾き2℃/分は、電力と水の量で決まります。' } }
    ],
    more: [
      { lv: 1, q: '350mAは何A?', a: '0.35A', exp: '1A = 1000mA なので、350 ÷ 1000 = 0.35A です。m(ミリ)は1000分の1を表します。' },
      { lv: 1, q: '25cm²は何m²?', a: '0.0025m²', exp: '1m = 100cm なので、1m² = 100 × 100 = 10000cm²。25 ÷ 10000 = 0.0025m² です。100でわるまちがいが多いので注意します。' },
      { lv: 1, q: '3分20秒は何秒?', a: '200秒', exp: '3分は 3 × 60 = 180秒、それに20秒を足して200秒です。電力量や発熱量の計算では、時間を秒に直します。' },
      { lv: 1, q: '水200gの温度を5℃上げるのに必要な熱量は何J?(水1gを1℃上げるのに4.2J)', a: '4200J', exp: '4.2 × 200 × 5 = 4200J です。「1gを1℃」あたりの量なので、質量と上昇温度の両方をかけます。' },
      { lv: 1, q: '水135gに食塩15gをとかした。質量パーセント濃度は何%?', a: '10%', exp: '食塩水全体は 135 + 15 = 150g です。15 ÷ 150 × 100 = 10%。水の質量135gでわらないよう注意します。' },
      { lv: 1, q: '15Ωの抵抗に3Vの電圧を加えた。流れる電流は何A?', a: '0.2A', exp: '電流 = 電圧 ÷ 抵抗 = 3 ÷ 15 = 0.2A です。mA で表すと200mAです。' },
      { lv: 1, q: '質量400gの物体を、面積0.02m²の面を下にして置いた。床が受ける圧力は何Pa?(100gの物体にはたらく重力を1Nとする)', a: '200Pa', exp: '400gの物体の重さは4Nです。圧力 = 4 ÷ 0.02 = 200Pa。質量(g)を力(N)に直してから計算します。' },
      { lv: 2, q: 'ある電熱線で水100gを4分間温めると5℃上がった。同じ電熱線で水250gを10分間温めると何℃上がる?(熱はすべて水に伝わる)', a: '5℃', exp: '時間は2.5倍で熱量は2.5倍、水も2.5倍なので上昇温度は 1/2.5 倍です。5 × 2.5 ÷ 2.5 = 5℃ で、変わりません。' },
      { lv: 2, q: '6Vの電圧で2Aの電流が流れる電熱線で、水200gを7分間温めた。熱がすべて水に伝わるとすると、水温は何℃上がる?(水1gを1℃上げるのに4.2J)', a: '6℃', exp: '電力は12W、時間は420秒で、発熱量は 12 × 420 = 5040J。上昇温度は 5040 ÷(4.2 × 200)= 5040 ÷ 840 = 6℃ です。' },
      { lv: 2, q: '5%の食塩水200gと15%の食塩水300gを混ぜた。何%の食塩水になる?', a: '11%', exp: '食塩は 10g + 45g = 55g、全体は500gです。55 ÷ 500 = 0.11 で11%。量が多い15%の側に近い値になります。' },
      { lv: 2, q: '20%の食塩水150gに水を加えて12%にしたい。水を何g加えればよい?', a: '100g', exp: '食塩は 150 × 0.2 = 30g です。12%で30gなら全体は 30 ÷ 0.12 = 250g。加える水は 250 − 150 = 100g です。' },
      { lv: 2, q: '自然長8cmのばねは、0.2Nの力で1cmのびる。ばねの長さが13cmになったとき、ばねを引く力は何N?', a: '1.0N', exp: 'のびは 13 − 8 = 5cm です。1cmで0.2Nなので、5cmでは 0.2 × 5 = 1.0N。長さ13cmをそのままのびとしないよう注意します。' },
      { lv: 2, q: '重さ50Nの板を、たて25cm・横20cmの面を下にして置いた。床が受ける圧力は何Pa?', a: '1000Pa', exp: '面積は 25 × 20 = 500cm² = 0.05m² です。圧力 = 50 ÷ 0.05 = 1000Pa。' },
      { lv: 2, q: '空気中で2.0Nを示す、体積30cm³の物体を全部水にしずめた。ばねばかりは何Nを示す?(水1cm³は1g、100gの物体にはたらく重力を1Nとする)', a: '1.7N', exp: '浮力は水30g分の重さで0.3Nです。ばねばかりの値は 2.0 − 0.3 = 1.7N になります。' },
      { lv: 2, q: '水温と加熱時間のグラフが直線になった。同じ量の水で、電力が2倍の電熱線にかえると、グラフの傾きとはじめの水温(切片)はどうなる?', a: '傾きは2倍になり、切片(はじめの水温)は変わらない。', exp: '1分あたりの発熱量が2倍なので、1分あたりの上昇温度(傾き)も2倍です。加熱前の水温は電熱線に関係ないので、切片は同じです。' },
      { lv: 3, q: '6%の食塩水と15%の食塩水を混ぜて、9%の食塩水を450gつくりたい。それぞれ何g混ぜればよい?', a: '6%を300g、15%を150g', exp: '15%を y g とすると、6%は(450 − y)g。食塩について 0.06(450 − y) + 0.15y = 450 × 0.09 = 40.5 より 27 + 0.09y = 40.5、y = 150。6%は300gです。' },
      { lv: 3, q: '1000Wの電気ポットで水500gを温めると、3分30秒で水温が80℃上がった。発生した熱の何%が水に伝わった?(水1gを1℃上げるのに4.2J)', a: '80%', exp: '発生した熱は 1000 × 210 = 210000J。水が得た熱は 4.2 × 500 × 80 = 168000J。168000 ÷ 210000 = 0.8 で80%です。' },
      { lv: 3, q: '4Ωと8Ωの電熱線を並列にして8Vの電源につなぎ、それぞれを別のビーカーの水100gに入れて3分30秒温めた。それぞれの水温は何℃上がる?(熱はすべて水に伝わり、水1gを1℃上げるのに4.2J)', a: '4Ωのほうは8℃、8Ωのほうは4℃', exp: '並列なのでどちらにも8V。4Ωは2Aで16W、8Ωは1Aで8Wです。16 × 210 = 3360J で 3360 ÷ 420 = 8℃、8Ωはその半分の4℃。並列では抵抗が小さいほうがよく発熱します。' },
      { lv: 3, q: '密度2.7g/cm³のアルミニウムでできた、たて2cm・横5cm・高さ10cmの直方体を、2cm×5cmの面を下にして立てた。床が受ける圧力は何Pa?(100gの物体にはたらく重力を1Nとする)', a: '2700Pa', exp: '体積は100cm³で、質量は 2.7 × 100 = 270g、重さ2.7Nです。面積は10cm² = 0.001m² なので、圧力 = 2.7 ÷ 0.001 = 2700Pa です。' },
      { lv: 3, q: '20%の食塩水100gに、食塩を10gと水を40g加えた。何%の食塩水になる?', a: '20%', exp: '食塩は 20 + 10 = 30g、全体は 100 + 10 + 40 = 150g です。30 ÷ 150 = 0.2 で20%。加えた「食塩10gと水40g」自体が20%の食塩水と同じ割合なので、濃度は変わりません。' }
    ]
  });

  add('sx_jh2', {
    pat: [
      { name: '長さ・面積・体積の単位のけたをそろえる', freq: 'とてもよく出る', when: 'cm と m、cm² と m²、cm³ と m³・L が混ざっている問題は、この型です。', how: ['まず長さの換算(1m = 100cm)を確かめます。', '面積は2回かけるので 1m² = 100 × 100 = 10000cm²。', '体積は3回かけるので 1m³ = 100 × 100 × 100 = 1000000cm³。1L = 1000cm³。', '「大きい単位 → 小さい単位」は数が大きくなる、と見当をつけて確かめます。'], ex: { q: '3m²は何cm²?', a: '30000cm²', exp: '1m² = 10000cm² なので、3 × 10000 = 30000cm² です。長さと同じように100倍して300cm²とするのが、いちばん多いまちがいです。' } },
      { name: 'km/h と m/s の換算', freq: 'とてもよく出る', when: '時速と秒速が混ざっている、または時間が「分」で与えられている速さの問題は、この型です。', how: ['1km = 1000m、1時間 = 3600秒 を使います。', 'km/h → m/s は ÷3.6、m/s → km/h は ×3.6。', '分のときは、時間(h)に直すなら ÷60、秒に直すなら ×60。'], ex: { q: '秒速15mは時速何km?', a: '時速54km', exp: '1時間 = 3600秒 で 15 × 3600 = 54000m = 54km 進むので、時速54kmです。15 × 3.6 = 54 と計算しても同じです。' } },
      { name: '電力量の換算(kWh・J・電気料金)', freq: 'よく出る', when: '「1日○時間、○日間」「電気料金」「kWh」「J」とあれば、この型です。', how: ['W を kW に直します(÷1000)。', 'kWh = kW × 時間(h)。分は時間に直します(÷60)。', 'J = W × 秒。1kWh = 1000 × 3600 = 3600000J。', '料金 = kWh × 1kWhあたりの料金。'], ex: { q: '600Wの電気器具を1日2時間、30日間使った。1kWhあたり30円とすると、電気料金は何円?', a: '1080円', exp: '600W = 0.6kW です。0.6 × 2 × 30 = 36kWh。料金は 36 × 30 = 1080円 です。W のまま計算すると1000倍の答えになってしまいます。' } },
      { name: '体積 → 質量 → 重さ → 圧力 をつなぐ', freq: 'よく出る', when: '「密度○g/cm³の立方体」「床が受ける圧力」とあり、質量が直接書かれていないときは、この型です。', how: ['体積を cm³ で求めます。', '質量 = 密度 × 体積(g)。', '重さ(N)= 質量(g)÷ 100(100gで1Nとして)。', '面積を m² に直し、圧力 = 重さ ÷ 面積。'], ex: { q: '1辺10cmの鉄の立方体(密度7.9g/cm³)を床に置いた。床が受ける圧力は何Pa?(100gの物体にはたらく重力を1Nとする)', a: '7900Pa', exp: '体積は1000cm³、質量は 7.9 × 1000 = 7900g、重さは79Nです。底面は100cm² = 0.01m² なので、圧力 = 79 ÷ 0.01 = 7900Pa です。' } },
      { name: '単位と大きさで答えを検算する', freq: 'よく出る', when: '計算が長い問題や、答えの単位をまちがえやすい問題では、最後にこの型を使います。', how: ['答えの単位が、求める量の単位になっているか確かめます(速さなら m/s など)。', '身近な値とくらべて、大きすぎたり小さすぎたりしないか見ます。', '別の方法(逆算・概算)で同じ答えになるか確かめます。'], ex: { q: '1辺2cmの立方体の質量が21.6gだった。ある人は密度を 21.6 ÷ 4 = 5.4g/cm³ と答えた。正しい密度と、まちがいの原因は?', a: '2.7g/cm³。体積(8cm³)ではなく底面積(4cm²)でわったため。', exp: '体積は 2 × 2 × 2 = 8cm³ なので、21.6 ÷ 8 = 2.7g/cm³ です。cm² でわると単位が g/cm² になり、密度の単位にならないことで、まちがいに気づけます。' } }
    ],
    more: [
      { lv: 1, q: '750cmは何m?', a: '7.5m', exp: '1m = 100cm なので、750 ÷ 100 = 7.5m です。' },
      { lv: 1, q: '250mLは何cm³?', a: '250cm³', exp: '1mL = 1cm³ です。1L = 1000mL = 1000cm³ もいっしょに覚えておきます。' },
      { lv: 1, q: '2時間15分は何時間?', a: '2.25時間', exp: '15分は 15 ÷ 60 = 0.25時間です。2時間15分を2.15時間とするまちがいに注意します。' },
      { lv: 1, q: '3.5kgは何g?', a: '3500g', exp: '1kg = 1000g なので、3.5 × 1000 = 3500g です。' },
      { lv: 1, q: '秒速20mは時速何km?', a: '時速72km', exp: '20 × 3600 = 72000m = 72km なので、時速72kmです。m/s の数値に3.6をかけても求められます。' },
      { lv: 1, q: '2000Wは何kW?', a: '2kW', exp: 'k(キロ)は1000倍を表すので、2000 ÷ 1000 = 2kW です。' },
      { lv: 1, q: '600cm²は何m²?', a: '0.06m²', exp: '1m² = 10000cm² なので、600 ÷ 10000 = 0.06m² です。' },
      { lv: 2, q: '時速54kmで20分間走ると、何km進む?', a: '18km', exp: '20分は 20 ÷ 60 = 1/3時間です。54 × 1/3 = 18km。分を時間に直してから、速さ × 時間 を計算します。' },
      { lv: 2, q: '秒速25mで走る自動車は、2分間に何km進む?', a: '3km', exp: '2分は120秒なので、25 × 120 = 3000m = 3km です。' },
      { lv: 2, q: '消費電力1200Wの電気器具を25分間使った。電力量は何kWh?', a: '0.5kWh', exp: '1200W = 1.2kW、25分 = 25/60時間です。1.2 × 25/60 = 0.5kWh。' },
      { lv: 2, q: '密度1.2g/cm³の液体3Lの質量は何kg?', a: '3.6kg', exp: '3L = 3000cm³ です。質量は 1.2 × 3000 = 3600g = 3.6kg です。' },
      { lv: 2, q: '質量2kgの物体を1.5mの高さまで持ち上げた。仕事は何J?(100gの物体にはたらく重力を1Nとする)', a: '30J', exp: '2kg = 2000g なので重さは20Nです。仕事 = 20 × 1.5 = 30J。kgのまま 2 × 1.5 = 3 としないよう注意します。' },
      { lv: 2, q: '仕事率1.2kWのモーターが5秒間にする仕事は何J?', a: '6000J', exp: '1.2kW = 1200W = 1200J/s です。5秒間で 1200 × 5 = 6000J。' },
      { lv: 2, q: '密度2.7g/cm³のアルミニウム1m³の質量は何kg?', a: '2700kg', exp: '1m³ = 1000000cm³ なので、質量は 2.7 × 1000000 = 2700000g = 2700kg です。g/cm³ の数値を1000倍すると kg/m³ の数値になります。' },
      { lv: 2, q: '1cm²あたり2Nの力がはたらいている。この圧力は何Pa?', a: '20000Pa', exp: '1m² = 10000cm² なので、1m²あたりでは 2 × 10000 = 20000N です。Pa は N/m² なので20000Paです。' },
      { lv: 3, q: '800Wの電気器具を1日3時間、30日間使った。1kWhあたり30円とすると、電気料金は何円?', a: '2160円', exp: '0.8kW × 3時間 × 30日 = 72kWh。料金は 72 × 30 = 2160円 です。' },
      { lv: 3, q: '1辺5cmの立方体の銅(密度9.0g/cm³)を床に置いた。床が受ける圧力は何Pa?(100gの物体にはたらく重力を1Nとする)', a: '4500Pa', exp: '体積は125cm³、質量は 9.0 × 125 = 1125g、重さは11.25Nです。底面は25cm² = 0.0025m² なので、11.25 ÷ 0.0025 = 4500Pa です。' },
      { lv: 3, q: '空気中の音の速さ340m/sは、時速何km?', a: '時速1224km', exp: '340 × 3.6 = 1224 なので時速1224kmです。340 × 3600 = 1224000m = 1224km と計算しても同じです。' },
      { lv: 3, q: '1kWhの電力量で、25WのLED電球を何時間つけられる?', a: '40時間', exp: '1kWh = 1000Wh です。25Wで使うと、1000 ÷ 25 = 40時間 つけられます。W と kW をそろえてからわり算します。' },
      { lv: 3, q: '体積30cm³の物体の質量を、ある人が「0.81g」と計算した。物体はアルミニウム(密度2.7g/cm³)だった。正しい質量と、この人のまちがいとして考えられるものは?', a: '81g。密度にかけるべき体積を、100でわってしまった(または単位を取りちがえた)と考えられる。', exp: '質量 = 2.7 × 30 = 81g です。30cm³ の金属が1gにも満たないのは、1円玉(約1g、約0.37cm³)とくらべても小さすぎるので、検算でまちがいに気づけます。' }
    ]
  });

  add('s_m3', {
    pat: [
      { name: '対照実験:変える条件は1つだけ', freq: 'とてもよく出る', when: '「○○が必要であることを確かめるには、どれとどれを比べればよいか」「対照実験」とあれば、この型です。', how: ['調べたい条件(光・二酸化炭素・葉緑体など)を1つ決めます。', 'その条件だけがちがい、ほかの条件はすべて同じ2つを選びます。', '2つの結果がちがえば、その条件が原因だといえます。'], ex: { q: 'BTB溶液を加えて青くした水を4本の試験管に入れ、A:水草+光、B:水草なし+光、C:水草+暗所、D:水草なし+暗所 とした。光合成に水草が必要なことを確かめるには、どれとどれを比べる?', a: 'AとB', exp: 'AとBは光の条件が同じで、水草があるかないかだけがちがいます。Aだけが変化すれば、変化は水草のはたらきによるといえます。AとDは2つの条件がちがうので比べられません。' } },
      { name: 'ワセリンを使った蒸散量の計算', freq: 'とてもよく出る', when: '「葉の表(裏)にワセリンをぬる」「水の減少量」とあれば、この型です。', how: ['それぞれの枝で、どこから蒸散しているかを書き出します(何もしない = 表 + 裏 + 茎)。', '表にぬった枝 = 裏 + 茎、裏にぬった枝 = 表 + 茎。', '何もしない枝から引き算して、表・裏・茎の量を1つずつ求めます。'], ex: { q: 'A:何もしない、B:葉の表にワセリン、C:葉の裏にワセリン とすると、水の減少量はA 10.0mL、B 7.5mL、C 3.0mLだった。葉の裏からの蒸散量は何mL?', a: '7.0mL', exp: 'Aは表+裏+茎、Cは表+茎です。裏 = A − C = 10.0 − 3.0 = 7.0mL。表は A − B = 2.5mL、茎は 10.0 − 2.5 − 7.0 = 0.5mL で、裏が最も多いことが分かります。' } },
      { name: '光合成と呼吸の差し引き', freq: 'よく出る', when: '「明るい所で吸収」「暗い所で放出」「1日で差し引き」とあれば、この型です。', how: ['明るい所で測った吸収量は「光合成 − 呼吸」(見かけの量)です。', '暗い所の放出量が、呼吸だけの量です。', '実際の光合成量 = 見かけの吸収量 + 呼吸量。', '1日の差し引きは「明るい時間 × 見かけの吸収量 − 暗い時間 × 呼吸量」。'], ex: { q: 'ある植物は、明るい所で1時間に二酸化炭素を15mg吸収し、暗い所で1時間に5mg放出する。実際に光合成で吸収している二酸化炭素は1時間あたり何mg?', a: '20mg', exp: '明るい所でも呼吸は続いていて、5mgを出しながら差し引き15mgを吸収しています。実際の光合成による吸収は 15 + 5 = 20mg です。' } },
      { name: '消化酵素と分解された物質の対応', freq: 'とてもよく出る', when: '「デンプン・タンパク質・脂肪」と「消化液」「最終的にできる物質」を結びつける問題は、この型です。', how: ['デンプン → ブドウ糖(だ液のアミラーゼ、すい液、小腸の壁の酵素)。', 'タンパク質 → アミノ酸(胃液のペプシン、すい液のトリプシン、小腸の壁の酵素)。', '脂肪 → 脂肪酸とモノグリセリド(すい液のリパーゼ。胆汁は酵素をふくまないが分解を助ける)。'], ex: { q: '胃液にふくまれる消化酵素ペプシンは、何を分解する?', a: 'タンパク質', exp: 'ペプシンはタンパク質を分解します。デンプンや脂肪は胃ではほとんど分解されません。タンパク質は最終的に小腸でアミノ酸になって吸収されます。' } },
      { name: '血液循環の経路と血液の性質', freq: 'よく出る', when: '「動脈血・静脈血」「酸素(養分・尿素)が最も多い血液」「肺循環・体循環」とあれば、この型です。', how: ['肺循環:右心室 → 肺動脈 → 肺 → 肺静脈 → 左心房。', '体循環:左心室 → 大動脈 → 全身 → 大静脈 → 右心房。', '酸素が多い血液(動脈血)は肺静脈と大動脈を流れ、肺動脈には静脈血が流れます。', '養分は小腸→肝臓の血管、尿素が少ないのは腎臓を出た血液、と器官のはたらきで考えます。'], ex: { q: '肺動脈を流れているのは、動脈血・静脈血のどちら?', a: '静脈血', exp: '肺動脈は、全身から心臓にもどってきた血液を肺へ送る血管なので、酸素が少ない静脈血が流れています。「動脈 = 動脈血」とはかぎりません。' } }
    ],
    more: [
      { lv: 1, q: '植物の細胞にはあって、動物の細胞にはふつう見られないつくりを3つ答えよう。', a: '細胞壁・葉緑体・(大きく発達した)液胞', exp: '核・細胞膜・細胞質は両方に共通です。植物は細胞壁で体を支え、葉緑体で光合成を行います。' },
      { lv: 1, q: '光合成の材料となる2つの物質は?', a: '二酸化炭素と水', exp: '光合成では、光のエネルギーを使って二酸化炭素と水からデンプンなどの養分をつくり、酸素を出します。' },
      { lv: 1, q: '胃液にふくまれる消化酵素は?', a: 'ペプシン', exp: 'ペプシンはタンパク質を分解する酵素です。だ液のアミラーゼはデンプン、すい液のリパーゼは脂肪を分解します。' },
      { lv: 1, q: '肺静脈を流れている血液は、動脈血・静脈血のどちら?', a: '動脈血', exp: '肺静脈は、肺で酸素を受けとった血液を心臓(左心房)にもどす血管なので、酸素の多い動脈血が流れています。' },
      { lv: 1, q: '単子葉類の葉脈は、どのような形?', a: '平行脈', exp: '単子葉類は葉脈が平行に並ぶ平行脈、双子葉類は網目状の網状脈です。根も、単子葉類はひげ根、双子葉類は主根と側根です。' },
      { lv: 1, q: 'まわりの温度が変わっても、体温をほぼ一定に保つことができるセキツイ動物のなかまを2つ答えよう。', a: '鳥類と哺乳類', exp: '体温をほぼ一定に保つ動物を恒温動物といいます。魚類・両生類・ハチュウ類は、まわりの温度で体温が変わる変温動物です。' },
      { lv: 1, q: '顕微鏡の接眼レンズが10倍、対物レンズが40倍のとき、倍率は何倍?', a: '400倍', exp: '顕微鏡の倍率は、接眼レンズの倍率 × 対物レンズの倍率 です。10 × 40 = 400倍。' },
      { lv: 2, q: '葉の数と大きさが同じ枝を2本用意し、Aは何もせず、Bは葉をすべてとって水にさした。水の減少量はA 12.0mL、B 1.0mLだった。葉からの蒸散量は何mL?', a: '11.0mL', exp: 'Aは葉と茎から、Bは茎だけから水が出ていきます。葉からの量は 12.0 − 1.0 = 11.0mL です。蒸散は主に葉の気孔で行われていることが分かります。' },
      { lv: 2, q: '血液の成分のうち、養分や二酸化炭素、不要な物質をとかして運ぶのは何?', a: '血しょう', exp: '血しょうは血液の液体の成分で、養分・二酸化炭素・尿素などをとかして運びます。酸素を運ぶのは赤血球です。' },
      { lv: 2, q: '水草を入れて緑色にしたBTB溶液の試験管を、一晩暗い所に置いた。液の色は何色になる?また、その理由は?', a: '黄色。暗い所では光合成が行われず、呼吸で出た二酸化炭素が水にとけて酸性になるから。', exp: '二酸化炭素が水にとけると酸性になり、BTB溶液は黄色になります。明るい所では光合成で二酸化炭素が使われ、青色に近づきます。' },
      { lv: 2, q: '小腸で吸収されたブドウ糖やアミノ酸は、まずどの器官に運ばれる?', a: '肝臓', exp: 'ブドウ糖とアミノ酸は柔毛の毛細血管に入り、小腸と肝臓をつなぐ血管(門脈)を通って肝臓へ運ばれます。肝臓では、ブドウ糖の一部がグリコーゲンとしてたくわえられます。' },
      { lv: 2, q: 'ヒトの心臓で、全身へ血液を送り出す部屋はどこ?また、その部屋のかべの特徴は?', a: '左心室。かべの筋肉が最も厚い。', exp: '左心室は、全身のすみずみまで血液を送り出すために強い力が必要で、筋肉のかべが最も厚くなっています。肺へ送る右心室のかべはそれよりうすいです。' },
      { lv: 2, q: 'クジラは何類のなかま?', choices: ['A 魚類', 'B 両生類', 'C ハチュウ類', 'D 哺乳類'], a: 'D(哺乳類)', exp: 'クジラは水中にすみますが、肺で呼吸し、子を母親の体内で育ててから産む(胎生)ので哺乳類です。すむ場所ではなく、呼吸や子の産み方で分類します。' },
      { lv: 2, q: '種子をつくらず、胞子でふえる植物はどれ?', choices: ['A イネ', 'B イヌワラビ', 'C マツ', 'D アブラナ'], a: 'B(イヌワラビ)', exp: 'イヌワラビはシダ植物で、胞子でふえます。イネとアブラナは被子植物、マツは裸子植物で、どれも種子でふえます。' },
      { lv: 2, q: '試験管Aにデンプン溶液とうすめただ液、試験管Bにデンプン溶液と水を入れ、40℃に10分間置いた。ベネジクト液を加えて加熱すると、赤褐色の沈殿ができるのはどちら?また、そこから分かることは?', a: 'A。だ液のはたらきで、デンプンが麦芽糖などに分解されたこと。', exp: 'ベネジクト液は、ブドウ糖が2つつながったもの(麦芽糖)などがあると赤褐色になります。水だけのBでは変化しないので、変化の原因はだ液だといえます。' },
      { lv: 3, q: 'ある植物は、明るい所で1時間に二酸化炭素を15mg吸収し、暗い所で1時間に5mg放出する(呼吸の量は一定)。1日のうち10時間明るく、14時間暗いとき、1日で差し引き何mgの二酸化炭素を吸収する?', a: '80mg', exp: '明るい10時間で 15 × 10 = 150mg 吸収し、暗い14時間で 5 × 14 = 70mg 放出します。差し引き 150 − 70 = 80mg の吸収で、その分だけ養分がたくわえられます。' },
      { lv: 3, q: 'A:何もしない、B:葉の表にワセリン、C:葉の裏にワセリン、D:葉の表と裏の両方にワセリン とした。A 9.0mL、B 6.5mL、C 3.0mL のとき、Dの水の減少量は何mLと考えられる?', a: '0.5mL', exp: '表 = A − B = 2.5mL、裏 = A − C = 6.0mL です。茎からは 9.0 − 2.5 − 6.0 = 0.5mL。Dは茎からだけ水が出るので0.5mLです。' },
      { lv: 3, q: '胆汁について正しいものはどれ?', choices: ['A すい臓でつくられ、デンプンを分解する', 'B 肝臓でつくられ、消化酵素をふくまないが、脂肪の消化を助ける', 'C 胃でつくられ、タンパク質を分解する', 'D 小腸でつくられ、脂肪を吸収する'], a: 'B(肝臓でつくられ、消化酵素をふくまないが、脂肪の消化を助ける)', exp: '胆汁は肝臓でつくられ、胆のうにたくわえられて小腸に出されます。脂肪を細かい粒にして、リパーゼがはたらきやすくします。' },
      { lv: 3, q: '次の(1)〜(3)にあてはまる血液が流れる血管を答えよう。(1) 酸素を最も多くふくむ (2) 食後、養分を最も多くふくむ (3) 尿素が最も少ない', a: '(1) 肺静脈 (2) 小腸から肝臓へ向かう血管(門脈) (3) 腎臓から出ていく血管(腎静脈)', exp: '酸素は肺でとり入れた直後、養分は小腸で吸収した直後が最も多くなります。尿素は腎臓でこし出されるので、腎臓を出た血液で最も少なくなります。' },
      { lv: 3, q: '顕微鏡の倍率が100倍のとき、視野の直径に細胞が20個並んで見えた。倍率を400倍にすると、視野の直径には何個並んで見える?', a: '5個', exp: '倍率が4倍になると、1個の細胞が4倍の長さに見えるので、視野の直径に並ぶ数は 20 ÷ 4 = 5個 になります。面積で考えて1/16にしないよう注意します。' }
    ]
  });

  add('s_cell', {
    pat: [
      { name: '遺伝の比:かけ合わせの表をかく', freq: 'とてもよく出る', when: '「AAとaa」「子の形質の比」「孫の数」とあれば、この型です。', how: ['両親の遺伝子の組み合わせから、生殖細胞の遺伝子(A か a)を書き出します。', 'たて・横に生殖細胞を並べた表をつくり、子の組み合わせを埋めます。', '顕性の遺伝子 A を1つでももてば顕性の形質が現れると考えて、形質の比を出します。', '数を聞かれたら、全体の数に比の割合をかけます。'], ex: { q: '丸(AA)としわ(aa)の純系をかけ合わせて子をつくり、子どうしをかけ合わせて孫を800個得た。しわの種子は約何個?(丸が顕性)', a: '約200個', exp: '子はすべて Aa です。Aa × Aa の孫は AA:Aa:aa = 1:2:1 で、丸:しわ = 3:1。しわは全体の1/4なので、800 × 1/4 = 200個 です。' } },
      { name: '顕性の個体が AA か Aa かを見分ける', freq: 'よく出る', when: '「丸い種子をつくる株の遺伝子の組み合わせを調べる」「しわの株とかけ合わせる」とあれば、この型です。', how: ['潜性の純系(aa)とかけ合わせます。aa の生殖細胞は a だけなので、相手の遺伝子がそのまま形質に出ます。', '子がすべて顕性なら AA、顕性:潜性 = 1:1 なら Aa と判断します。'], ex: { q: '丸い種子の株Xを、しわの株(aa)とかけ合わせると、丸としわが約1:1でできた。株Xの遺伝子の組み合わせは?', a: 'Aa', exp: '株Xが AA なら子はすべて Aa で丸になります。しわ(aa)が出たのは、株Xが a をもっていたからです。Aa × aa は Aa:aa = 1:1 で、結果と一致します。' } },
      { name: '体細胞分裂の順序と観察の手順', freq: 'よく出る', when: '「タマネギの根」「塩酸」「酢酸カーミン(酢酸オルセイン)」「分裂の順に並べる」とあれば、この型です。', how: ['根の先端近く(成長点)を使います。分裂がさかんだからです。', 'うすい塩酸で細胞どうしをはなれやすくし、染色液で核や染色体を染めます。', '順序は「核の中に染色体が見える → 中央に並ぶ → 両はしに分かれる → しきりができて2つの細胞」。'], ex: { q: 'タマネギの根の細胞分裂を観察するとき、根をあたためたうすい塩酸に入れるのはなぜ?', a: '細胞どうしをはなれやすくし、プレパラートで細胞を重ならないように広げるため。', exp: '塩酸で細胞どうしの結びつきを弱めると、カバーガラスの上からおしつぶしたときに細胞が1層に広がり、1つ1つの細胞が観察しやすくなります。' } },
      { name: '染色体の数(体細胞・生殖細胞・受精卵)', freq: 'よく出る', when: '「体細胞の染色体は○本」「精子・卵・受精卵は何本」とあれば、この型です。', how: ['体細胞分裂では、もとの細胞と同じ数の染色体が子の細胞に入ります。', '減数分裂でできる生殖細胞は、体細胞の半分です。', '受精卵は2つの生殖細胞が合わさるので、体細胞と同じ数にもどります。'], ex: { q: 'イヌの体細胞の染色体は78本である。イヌの卵の染色体は何本?', a: '39本', exp: '卵は減数分裂でできる生殖細胞なので、体細胞の半分の 78 ÷ 2 = 39本 です。精子も39本で、受精卵は 39 + 39 = 78本 にもどります。' } },
      { name: '進化の証拠と生物の移り変わり', freq: 'よく出る', when: '「相同器官」「シソチョウ」「セキツイ動物が現れた順」とあれば、この型です。', how: ['形やはたらきがちがっても、骨格のつくりが同じなら、共通の祖先から変化したと考えます(相同器官)。', '2つのなかまの特徴をあわせもつ生物は、その間をつなぐ証拠です。', 'セキツイ動物は、魚類 → 両生類 → ハチュウ類 → 哺乳類・鳥類 の順に現れたと考えられています。'], ex: { q: 'セキツイ動物の5つのなかまのうち、最も古い時代に地球上に現れたと考えられるのはどれ?', a: '魚類', exp: '化石の記録から、まず水中に魚類が現れ、その後、両生類、ハチュウ類が陸上に広がり、ハチュウ類から哺乳類や鳥類が分かれたと考えられています。' } }
    ],
    more: [
      { lv: 1, q: '1つの細胞が2つに分かれることを何という?', a: '細胞分裂', exp: '多細胞生物は、細胞分裂で細胞の数をふやし、ふえた細胞が大きくなることで成長します。' },
      { lv: 1, q: '親の体の一部が分かれて、そのまま新しい個体になるふえ方を何という?', a: '無性生殖', exp: '無性生殖では受精を行わないので、子は親とまったく同じ遺伝子を受けつぎます。ゾウリムシの分裂やジャガイモのいもなどがその例です。' },
      { lv: 1, q: '動物の卵と精子が受精してできる細胞を何という?', a: '受精卵', exp: '受精卵は細胞分裂をくり返して胚になり、やがて親と同じような体のつくりをもつ個体になります。この過程を発生といいます。' },
      { lv: 1, q: '丸の純系としわの純系をかけ合わせたとき、子に現れるほうの形質を何という?', a: '顕性形質', exp: '子に現れる形質を顕性形質、現れない形質を潜性形質といいます。エンドウの種子では丸が顕性です。' },
      { lv: 1, q: '被子植物で受精が起こったあと、胚珠と子房はそれぞれ何になる?', a: '胚珠は種子に、子房は果実になる。', exp: '受精卵は胚珠の中で胚になり、胚珠全体が種子になります。胚珠を包む子房はふくらんで果実になります。' },
      { lv: 1, q: 'シイタケやアオカビは、何のなかま?', a: '菌類', exp: 'シイタケ(キノコ)やアオカビは菌類で、体は菌糸でできています。生態系では、有機物を無機物に分解する分解者です。' },
      { lv: 1, q: '親から子へ形質が伝わることを何という?', a: '遺伝', exp: '形質を伝えるもとになるのが遺伝子で、遺伝子は細胞の核の中の染色体にあります。遺伝子の本体は DNA です。' },
      { lv: 2, q: 'エンドウの子(Aa)どうしをかけ合わせて孫を1200個得た。丸い種子は約何個?(丸が顕性)', a: '約900個', exp: 'Aa × Aa の孫は AA:Aa:aa = 1:2:1 で、丸:しわ = 3:1 です。丸は 1200 × 3/4 = 900個 です。' },
      { lv: 2, q: '有性生殖によるふえ方はどれ?', choices: ['A サツマイモをいもからふやす', 'B ゾウリムシが分裂してふえる', 'C カエルが卵を産んでふえる', 'D 植物をさし木でふやす'], a: 'C(カエルが卵を産んでふえる)', exp: 'カエルは卵と精子が受精してできた受精卵からふえるので、有性生殖です。ほかは受精を行わない無性生殖です。' },
      { lv: 2, q: 'イヌの体細胞の染色体は78本である。イヌの精子と受精卵の染色体はそれぞれ何本?', a: '精子39本、受精卵78本', exp: '精子は減数分裂でできるので半分の39本、受精卵は卵と精子が合わさるので 39 + 39 = 78本 です。' },
      { lv: 2, q: '生殖細胞ができるときに減数分裂が行われることで、どのような点がよいか。', a: '受精しても、子の染色体の数が親と同じに保たれる。', exp: '生殖細胞の染色体を半分にしておけば、2つが合わさった受精卵は親と同じ数になります。減数分裂がなければ、世代ごとに染色体が2倍にふえてしまいます。' },
      { lv: 2, q: 'ある地域で、草食動物の数が急に減った。そのあと、植物と肉食動物の数はそれぞれ一時的にどうなると考えられる?', a: '植物はふえ、肉食動物は減る。', exp: '食べられる植物はふえ、えさが減った肉食動物は減ります。すると植物が多いので草食動物がまたふえ、長い時間がたつと、もとのつり合いにもどっていきます。' },
      { lv: 2, q: '体細胞分裂の観察で、根の先端近くを使う理由は?', a: '先端近く(成長点)では細胞分裂がさかんに行われていて、分裂中の細胞が多く見られるから。', exp: '根の先端近くで細胞がふえ、少し上の部分で1つ1つの細胞が大きくなって根がのびます。根もとに近い部分では分裂はほとんど見られません。' },
      { lv: 2, q: 'AAの株とaaの株をかけ合わせてできた子を、aaの株とかけ合わせた。できる種子の丸としわの比は?(丸が顕性)', a: '丸:しわ = 1:1', exp: '子はすべて Aa です。Aa × aa では Aa:aa = 1:1 になるので、丸:しわ = 1:1 です。' },
      { lv: 2, q: '花粉が柱頭についたあと、花粉管が胚珠に向かってのびる。花粉管の中を通って運ばれる生殖細胞を何という?', a: '精細胞', exp: '花粉管の中を精細胞が運ばれ、胚珠の中の卵細胞と受精します。被子植物では、精子ではなく精細胞とよびます。' },
      { lv: 3, q: 'Aa × Aa でできた孫(AA:Aa:aa = 1:2:1)のすべてを、それぞれ aa の株とかけ合わせた。どの株からも同じ数の種子ができるとすると、種子全体の丸としわの比は?', a: '丸:しわ = 1:1', exp: 'AA × aa → すべて丸、Aa × aa → 丸:しわ = 1:1、aa × aa → すべてしわ。丸の割合は 1/4 × 1 + 2/4 × 1/2 = 1/2 で、しわも1/2なので1:1です。' },
      { lv: 3, q: '体細胞の染色体が6本(3対)の生物がつくる生殖細胞の、染色体の組み合わせは何通り?(染色体の一部の入れかわりは考えない)', a: '8通り', exp: '3対のそれぞれから、どちらか1本を選んで生殖細胞に入れます。2 × 2 × 2 = 8通り です。この組み合わせの多さが、子の形質の多様性につながります。' },
      { lv: 3, q: 'Aa × Aa でできた孫を1600個集めた。孫がもつ遺伝子 A と遺伝子 a の数の比は?(1個体は遺伝子を2つもつ)', a: 'A:a = 1:1', exp: '孫は AA 400個、Aa 800個、aa 400個です。A は 400 × 2 + 800 = 1600、a も 800 + 400 × 2 = 1600 で同じ数です。形質の比は3:1でも、遺伝子の数は1:1です。' },
      { lv: 3, q: '丸い種子をつくる株どうしをかけ合わせたところ、しわの種子ができた。両親の遺伝子の組み合わせと、できる種子のうちしわの割合は?(丸が顕性)', a: '両親ともに Aa。しわは全体の1/4。', exp: 'しわ(aa)の子ができるには、両親が a を1つずつもっている必要があります。丸い株で a をもつのは Aa なので、Aa × Aa で、aa は1/4です。' },
      { lv: 3, q: 'デンプン溶液に、A:林の土を水でとかした上ずみ液、B:その土を十分に焼いてから同じようにした上ずみ液 を入れて数日置き、ヨウ素液を加えた。青紫色になるのはどちら?その理由は?', a: 'B。焼いたことで土の中の微生物が死に、デンプンが分解されなかったから。', exp: 'Aでは土の中の菌類・細菌類(分解者)がデンプンを分解したので、ヨウ素液は反応しません。Bは条件を1つだけ変えた対照実験で、分解が微生物のはたらきであることが確かめられます。' }
    ]
  });

  add('s_m4', {
    pat: [
      { name: '地震の到着時刻から速さと発生時刻を求める', freq: 'とてもよく出る', when: '「地点A・Bの震源からの距離とP波(S波)の到着時刻」の表があれば、この型です。', how: ['2地点の「距離の差」と「到着時刻の差」から、波の速さ = 距離の差 ÷ 時刻の差。', '1地点の距離 ÷ 速さ で、震源からその地点までにかかった時間を出します。', '到着時刻からその時間を引くと、地震の発生時刻です。', '初期微動継続時間は震源からの距離に比例します。'], ex: { q: '震源から36kmの地点Aに9時0分6秒、84kmの地点Bに9時0分14秒にP波が届いた。P波の速さと、地震の発生時刻は?', a: '6km/s、9時0分0秒', exp: '距離の差は48km、時刻の差は8秒なので、速さは 48 ÷ 8 = 6km/s です。Aまでは 36 ÷ 6 = 6秒 かかるので、発生時刻は 9時0分6秒 の6秒前の9時0分0秒です。' } },
      { name: '湿度と露点・出てくる水滴の量', freq: 'とてもよく出る', when: '「飽和水蒸気量の表」「露点」「湿度は何%」「水滴は何g」とあれば、この型です。', how: ['空気1m³中の水蒸気の量を出します(露点が分かれば、露点での飽和水蒸気量がその量)。', '湿度 = 水蒸気の量 ÷ その気温の飽和水蒸気量 × 100。', '冷やしたときの水滴 = 水蒸気の量 − 冷やした温度での飽和水蒸気量。'], ex: { q: '気温20℃(飽和水蒸気量17.3g/m³)で、露点が10℃(9.4g/m³)の空気の湿度は約何%?', a: '約54%', exp: '露点が10℃なので、空気1m³中の水蒸気は9.4gです。湿度 = 9.4 ÷ 17.3 × 100 = 54.3… で約54%。露点の飽和水蒸気量が「実際の水蒸気量」だと気づくことがポイントです。' } },
      { name: '雲ができ始める高さ', freq: 'よく出る', when: '「空気が上昇する」「100mにつき1℃下がる」「何mで雲ができ始めるか」とあれば、この型です。', how: ['雲ができ始めるのは、上昇した空気の温度が露点まで下がったときです。', '気温 − 露点 = 下がる必要のある温度。', 'それを100mで1℃の割合で高さに直します。'], ex: { q: '地表で気温24℃、露点16℃の空気が上昇した。何mの高さで雲ができ始める?(雲ができるまでは100mにつき1℃下がり、露点は変わらないとする)', a: '800m', exp: '気温が露点まで 24 − 16 = 8℃ 下がると、水蒸気が水滴になり始めます。100mで1℃なので、8 × 100 = 800m です。' } },
      { name: '柱状図とかぎ層で地層の傾きを読む', freq: 'よく出る', when: '「火山灰の層」「柱状図」「地点の標高」「地層はどちらに傾いているか」とあれば、この型です。', how: ['同じ時期に広く積もった層(火山灰の層など)を「かぎ層」として選びます。', '各地点で、かぎ層の上面の標高 = 地表の標高 − 地表からの深さ を求めます。', '標高が低い地点の方向に、地層が下がって(傾いて)います。'], ex: { q: '地点A(標高60m)では地表から10mの深さに、地点B(標高50m)では地表から15mの深さに、同じ火山灰の層の上面があった。地層はどちらの地点の方向に低くなっている?', a: '地点Bの方向', exp: 'かぎ層の標高は、Aで 60 − 10 = 50m、Bで 50 − 15 = 35m です。Bのほうが15m低いので、地層はBの方向に低くなっています。深さだけで比べると判断をまちがえます。' } },
      { name: '前線の通過と天気の変化', freq: 'とてもよく出る', when: '「気温・湿度・気圧・風向の記録」「どの時間帯に前線が通過したか」とあれば、この型です。', how: ['寒冷前線:通過時に強い雨が短時間、通過後は気温が急に下がり、風向が北寄りに変わります。', '温暖前線:おだやかな雨が長時間、通過後は気温が上がり、風向が南寄りに変わります。', '記録の中で、気温と風向が急に変わった時間帯をさがします。'], ex: { q: '午後2時から3時の間に、にわか雨が降って気温が5℃下がり、風向が南西から北西に変わった。このとき通過した前線は?', a: '寒冷前線', exp: '短い時間の強い雨、気温の急な低下、北寄りの風への変化は、寒冷前線の通過の特徴です。寒冷前線の後ろには冷たい空気があるため、気温が下がります。' } }
    ],
    more: [
      { lv: 1, q: 'マグマのねばりけが強い火山は、どんな形になりやすい?また、溶岩の色は?', a: 'ドーム状(おわんをふせた形)で、溶岩は白っぽい。', exp: 'ねばりけの強いマグマは流れにくく、盛り上がった形になり、噴火は激しくなりがちです。ねばりけが弱いと、傾きのゆるやかな形で黒っぽい溶岩になります。' },
      { lv: 1, q: '火山岩に見られる、細かい粒(石基)の中に大きな結晶(斑晶)が散らばったつくりを何という?', a: '斑状組織', exp: '火山岩は、マグマが地表や地表近くで急に冷えてできるので、結晶になりきれない石基ができます。深成岩は大きな結晶がそろった等粒状組織です。' },
      { lv: 1, q: 'ある地点での地震のゆれの大きさを表すものを何という?', a: '震度', exp: '震度は観測地点ごとのゆれの大きさで、0〜7の10段階(5と6に強・弱)で表します。地震そのものの規模はマグニチュードです。' },
      { lv: 1, q: 'サンゴの化石が見つかった地層は、どんな環境で堆積したと考えられる?', a: 'あたたかくて浅い海', exp: 'サンゴはあたたかく浅い海にすむので、その化石は当時の環境を示す示相化石になります。' },
      { lv: 1, q: '空気を冷やしていったとき、水蒸気が水滴に変わり始める温度を何という?', a: '露点', exp: '露点では、空気中の水蒸気の量がちょうど飽和水蒸気量と等しく、湿度は100%です。' },
      { lv: 1, q: '低気圧の中心付近では、どんな空気の流れがあり、天気はどうなりやすい?', a: '上昇気流があり、雲ができやすく、くもりや雨になりやすい。', exp: '低気圧では、まわりから風が反時計回りにふきこみ、中心で上昇気流になります。上昇した空気が冷えて雲ができます。' },
      { lv: 1, q: '温暖前線が通過したあと、気温はどうなる?', a: '上がる。', exp: '温暖前線の後ろには、あたたかい空気があるからです。寒冷前線の通過後は、反対に気温が下がります。' },
      { lv: 2, q: 'P波の速さが7km/s、S波の速さが4km/sの地域で、震源から84kmの地点の初期微動継続時間は何秒?', a: '9秒', exp: 'P波は 84 ÷ 7 = 12秒後、S波は 84 ÷ 4 = 21秒後に届きます。差は 21 − 12 = 9秒 です。' },
      { lv: 2, q: '気温15℃の空気1m³に水蒸気が6.4gふくまれている。湿度は何%?(15℃の飽和水蒸気量は12.8g/m³)', a: '50%', exp: '湿度 = 6.4 ÷ 12.8 × 100 = 50% です。' },
      { lv: 2, q: '地表で気温26℃、露点14℃の空気が上昇した。何mの高さで雲ができ始める?(雲ができるまでは100mにつき1℃下がり、露点は変わらないとする)', a: '1200m', exp: '下がる必要があるのは 26 − 14 = 12℃ です。100mで1℃なので、12 × 100 = 1200m で雲ができ始めます。' },
      { lv: 2, q: '凝灰岩の層が見られた。この層ができた当時、どんなできごとがあったと考えられる?', a: '近くで火山の噴火があった。', exp: '凝灰岩は、火山灰などの火山の噴出物が積もって固まった岩石です。広い範囲に同時に積もるので、離れた地層を対比するかぎ層にもなります。' },
      { lv: 2, q: '深成岩が、大きな結晶がそろったつくり(等粒状組織)になっているのはなぜ?', a: 'マグマが地下深くで、長い時間をかけてゆっくり冷えて固まったから。', exp: 'ゆっくり冷えると、結晶が大きく成長する時間があります。地表近くで急に冷えた火山岩は、斑晶と石基の斑状組織になります。' },
      { lv: 2, q: 'よく晴れた日の昼、海岸付近では海から陸に向かって風がふくことが多い。その理由は?', a: '陸のほうが海よりあたたまりやすく、陸上で上昇気流ができて気圧が低くなるから。', exp: '陸の空気があたたまって上昇し、気圧が低くなった陸へ、海の上から空気が流れこみます(海風)。夜は陸のほうが冷えやすく、陸から海へ風がふきます(陸風)。' },
      { lv: 2, q: '6月ごろ、日本付近に長くとどまって雨の日が続く原因になる前線の名前と、前線をつくる2つの気団は?', a: '梅雨前線(停滞前線)。オホーツク海気団と小笠原気団。', exp: '冷たく湿ったオホーツク海気団と、あたたかく湿った小笠原気団の勢力がつり合い、前線がほとんど動かなくなります。小笠原気団が強まると前線は北へ去り、梅雨明けになります。' },
      { lv: 2, q: '震源から48kmの地点に、P波が10時30分18秒に届いた。P波の速さを6km/sとすると、地震が発生した時刻は?', a: '10時30分10秒', exp: 'P波が48km進むのに 48 ÷ 6 = 8秒 かかります。到着時刻の8秒前なので、10時30分10秒に発生しました。' },
      { lv: 3, q: '気温25℃、湿度60%の空気1m³を10℃まで冷やした。出てくる水滴は約何g?(飽和水蒸気量:25℃で23.1g/m³、10℃で9.4g/m³)', a: '約4.5g', exp: '水蒸気の量は 23.1 × 0.6 = 13.86g です。10℃では9.4gまでしかふくめないので、13.86 − 9.4 = 4.46 で約4.5gの水滴が出てきます。' },
      { lv: 3, q: 'P波の速さ6km/s、S波の速さ4km/sの地域で、震源から24kmの地震計がP波を感知し、その3秒後に緊急地震速報が出された。震源から80kmの地点では、速報が出てから何秒後にS波が届く?', a: '13秒後', exp: 'P波は24kmの地点に 24 ÷ 6 = 4秒後に届き、速報は地震発生の 4 + 3 = 7秒後です。80kmの地点にS波が届くのは 80 ÷ 4 = 20秒後なので、20 − 7 = 13秒後です。' },
      { lv: 3, q: '地表(0m)で気温20℃、露点12℃の空気が、高さ1800mの山をこえて反対側のふもと(0m)まで下りた。ふもとでの気温は何℃?(雲がないときは100mにつき1℃、雲があるときは100mにつき0.5℃変化する。山頂までに雲ができ、下りるときは雲が消えているとする)', a: '25℃', exp: '800mで露点の12℃になり、雲ができます。残り1000mは0.5℃ずつ下がり、山頂は 12 − 5 = 7℃。下りる1800mは1℃ずつ上がるので、7 + 18 = 25℃ です(フェーン現象)。' },
      { lv: 3, q: '地点A(標高80m)では地表から20mの深さに、地点B(標高70m)では地表から5mの深さに、同じ火山灰の層の上面があった。この火山灰の層の上面の標高は、それぞれ何m?また、地層はどちらの方向に低くなっている?', a: 'A 60m、B 65m。Aの方向に低くなっている。', exp: 'Aは 80 − 20 = 60m、Bは 70 − 5 = 65m です。地表はAのほうが高いのに、火山灰の層はAのほうが5m低いので、地層はAの方向に低くなっています。' },
      { lv: 3, q: '夏に日本の太平洋側からふく季節風の向きと、その風のもとになる気団は?また、夏の天気図に多い気圧配置は?', a: '南東の季節風、小笠原気団。南高北低の気圧配置。', exp: '夏は、太平洋上の小笠原気団(太平洋高気圧)が発達し、南に高気圧、北に低気圧の配置になります。そこから南東の季節風がふき、むし暑い晴れの日が続きます。' }
    ]
  });

})(WPS.LESSONS);
